  ["_CeladonMart3FGameBoyKid1Text"] = "I POKéMON\ncatturati\vregistrano un Num.\vID e AO, il nome\vdell'Allenatore\vOriginale che li\vha catturati!",
  ["_CeladonMart3FGameBoyKid2Text"] = "Bene! Il mio amico\nmi scambia il suo\vKANGASKHAN per il\vmio GRAVELER!",
  ["_CeladonMart3FGameBoyKid3Text"] = "Forza GRAVELER!\nAdoro GRAVELER! Li\vcolleziono! Eh?\vGRAVELER si é\vtrasformato in un\valtro POKéMON!",
  ["_CeladonMart3FLittleBoyText"] = "Puoi identificare\ni POKéMON presi\vnegli scambi dal\vloro Numero ID!",
  ["_CeladonMart3FPokemonPosterText"] = "Rosso e Blu! Sono\nentrambi POKéMON!",
  ["_CeladonMart3FPuzzleGameText"] = "Un puzzle game!\nCrea dipendenza!",
  ["_CeladonMart3FRPGText"] = "Un GdR! Non c'é\ntempo per quello!",
  ["_CeladonMart3FSNESText"] = "é un Super NES!",
  ["_CeladonMart3FSportsGameText"] = "Un gioco di sport!\nAl babbo piacera'!",
  ["_CeladonMart4FCurrentFloorSignText"] = "Esprimiti con i\nregali! 4P: REGALI\vSAGGI Speciale\vEvoluzione! PIETRE\velementari in\vofferta!",
  ["_CeladonMart4FSuperNerdText"] = "Prendo una BAMBOLA\nPOKé per la mia\vragazza!",
  ["_CeladonMart4FYoungsterText"] = "Ho sentito una\ncosa utile. Puoi\vfuggire dai\vPOKéMON selvatici\vdistraendoli con\vuna BAMBOLA POKé!",
  ["_CeladonMart5FCurrentFloorSignText"] = "5P: ERBORISTERIA",
  ["_CeladonMart5FGentlemanText"] = "I potenziatori di\nstatistiche si\vcomprano solo qui.\vUsa CALCIO per\vaumentare le\vabilita' SPECIALI.\vUsa CARBURANTE per\vaumentare la\vVELOCITA'.",
  ["_CeladonMart5FSailorText"] = "Sono qui per i\npotenziatori!\vPROTEINA aumenta\vil Attacco. FERRO\vaumenta la DIFESA!",
  ["_CeladonMartRoofCurrentFloorSignText"] = "REPARTO SUL TETTO:\nDISTRIBUTORI",
  ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "Ho sete! Voglio\nqualcosa da bere!\vLe dai da bere?",
  ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "Quale bibita le\ndai?",
  ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "No, grazie! Alla\nfine non ho piu'\vsete!",
  ["_CeladonMartRoofLittleGirlImThirstyText"] = "Ho sete! Voglio\nqualcosa da bere!",
  ["_CeladonMartRoofLittleGirlNoRoomText"] = "Non hai spazio per\nquesto!",
  ["_CeladonMartRoofLittleGirlReceivedTM13Text"] = "{PLAYER} ha\nricevuto\v{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM48Text"] = "{PLAYER} ha\nricevuto\v{RAM:wStringBuffer}!",
  ["_CeladonMartRoofLittleGirlReceivedTM49Text"] = "{PLAYER} ha\nricevuto MT49!",
  ["_CeladonMartRoofLittleGirlTM13ExplanationText"] = "{RAM:wStringBuffer}\ncontiene\vGELOPUNTO! A volte\vpuo' congelare il\vbersaglio!",
  ["_CeladonMartRoofLittleGirlTM48ExplanationText"] = "{RAM:wStringBuffer}\ncontiene FRANA! A\vvolte puo'\vspaventare il\vbersaglio!",
  ["_CeladonMartRoofLittleGirlTM49ExplanationText"] = "La MT49 contiene\nTRIPLICE ATTACCO!",
  ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "Evviva! ACQUA\nFRESCA! Grazie!\vPuoi prendere\vquesto da parte\vmia!",
  ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "Evviva! LIMONATA!\nGrazie! Puoi\vprendere questo da\vparte mia!",
  ["_CeladonMartRoofLittleGirlYaySodaPopText"] = "Evviva! BIBITA!\nGrazie! Puoi\vprendere questo da\vparte mia!",
  ["_CeladonMartRoofSuperNerdText"] = "Mia sorella é\nun'allenatrice ci\vcredi o no. Ma é\vcosi' immatura che\vmi fa impazzire!",
  ["_CeladonPokecenterBeautyText"] = "Ho pedalato in\nsalita sulla PISTA\vCICLABILE da\vFUCSIAPOLI!",
  ["_CeladonPokecenterGentlemanText"] = "Il FLAUTO POKé\nsveglia i POKéMON\vcon un suono che\vsentono solo loro!",
  ["_CeruleanBadgeHouseBoulderBadgeText"] = "L'ATTACCO di tutti\ni POKéMON aumenta\vun pochino.\vPermette anche di\vusare FLASH ogni\vvolta che lo\vdesideri.",
  ["_CeruleanBadgeHouseCascadeBadgeText"] = "I POKéMON fino al\nLv. 30\vubbidiranno. Piu'\valti, diventeranno\vinsoffrenti!\vPermette anche di\vusare TAGLIO fuori\vdallotta.",
  ["_CeruleanBadgeHouseEarthBadgeText"] = "Tutti i POKéMON ti\nubbidiranno!",
  ["_CeruleanBadgeHouseMarshBadgeText"] = "I POKéMON fino al\nLv. 70\vubbidiranno. Piu'\valti, diventeranno\vinsoffrenti!",
  ["_CeruleanBadgeHouseMiddleAgedManText"] = "Le MEDAGLIE\nPOKéMON sono\vpossedute solo da\vesperti. Vedo che\vne hai almeno una.\vQuelle medaglie\vhanno segreti\vincredibili!",
  ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "Vieni a trovarmi\nquando vuoi.",
  ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "Dunque... Quale\ndelle 8 medaglie\vdevo descrivere?",
  ["_CeruleanBadgeHouseRainbowBadgeText"] = "I POKéMON fino al\nLv. 50\vubbidiranno. Piu'\valti, diventeranno\vinsoffrenti!\vPermette anche di\vusare FORZA fuori\vdalla lotta.",
  ["_CeruleanBadgeHouseSoulBadgeText"] = "La DIFESA di tutti\ni POKéMON aumenta\vun pochino.\vPermette anche di\vusare SURF fuori\vdalla lotta.",
  ["_CeruleanBadgeHouseThunderBadgeText"] = "La VELOCITA' di\ntutti i POKéMON\vaumenta un\vpochino. Permette\vanche di usare\vVOLO fuori dalla\vlotta.",
  ["_CeruleanBadgeHouseVolcanoBadgeText"] = "Le abilita'\nSPECIALI dei tuoi\vPOKéMON aumentano\vun po'.",
  ["_CeruleanCityBikeShopSign"] = "Erba e grotte\naffrontate facili!\vNEGOZIO BICI",
  ["_CeruleanCityCooltrainerF1SlowbroPunchText"] = "Pugno SLOWBRO! No!\nHai sbagliato di\vnuovo!",
  ["_CeruleanCityCooltrainerF1SlowbroUseSonicboomText"] = "Ok! SLOWBRO! Usa\nSONICBOOM! Forza,\vSLOWBRO presta\vattenzione!",
  ["_CeruleanCityCooltrainerF1SlowbroWithdrawText"] = "SLOWBRO, RITIRATA!\nNo! é sbagliato! é\vcosi' difficile\vcontrollare i\vPOKéMON!\vL'ubbidienza\vdipende 膵dalle tue\vabilita' di\vallenatore!",
  ["_CeruleanCityCooltrainerF2Text"] = "Voglio una\nBICICLETTA rosso\vfuoco! La terro'\vin casa cosi' non\vsi sporca!",
  ["_CeruleanCityCooltrainerMText"] = "Sei un allenatore\nanche tu?\vCollezionare e\vlottare é dura.",
  ["_CeruleanCityGuardText"] = "La gente qui é\nstata rapinata. é\vovvio che il TEAM\vROCKET é dietro\vquesto efferato\vcrimine! Anche la\vPOLIZIA ha\vproblemi con i\vROCKET!",
  ["_CeruleanCityGymSign"] = "CELESTOPOLI\nPALESTRA POKéMON\vCAPOPALESTRA:\vMISTY La Sirenetta\vSanguigna",
  ["_CeruleanCityRivalDefeatedText"] = "Ehi! Calma! Hai\ngia' vinto!",
  ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}: Ehi,\nsapevi? Sono\vandato da BILL e\vmi ha fatto vedere\vi suoi rari\vPOKéMON! Ha\vaggiunto molte\vpagine al mio\vPOKéDEX!\vD'altronde, BILL é\vfamoso nel mondo\vcome POKéMANIAC!\vHa inventato il\vSistema Memoria\vPOKéMON su PC!\vVisto che usi il\vsuo sistema,\vringrazialo! Beh,\vdevo filare! Ci\vbecchiamo!",
  ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}: Ehi!\n{PLAYER}! Te la\vstrascichi ancora\vqui dietro? Io me\vla cavo alla\vgrande! Ho\vcatturato un bel\vpo' di POKéMON\vforti e\vintelligenti!\vEcco, fammi vedere\vcosa hai\vcatturato,\v{PLAYER}!",
  ["_CeruleanCityRivalVictoryText"] = "Heh! Non sei alla\naltezza del mio\vgenio!",
  ["_CeruleanCityRocketIBetterGetMovingText"] = "Devo proprio\nmuovermi! Ciao!",
  ["_CeruleanCityRocketIGiveUpText"] = "Fermati! Mi\narrendo! Me ne\vvado quatto\vquatto!",
  ["_CeruleanCityRocketIllReturnTheTMText"] = "Ok! Resituiro' la\nMT che ho rubato!",
  ["_CeruleanCityRocketReceivedTM28Text"] = "{PLAYER} ha\nrecuperato la\vMT28!",
  ["_CeruleanCityRocketTM28NoRoomText"] = "Fai spazio per\nquesto! Non posso\vmuovermi finché\vnon te la do!",
  ["_CeruleanCityRocketText"] = "Ehi! Fuori! Não é\nil tuo cortile!\vEh? Io? Sono un\vinnocente\vpassante! Non mi\vcredi?",
  ["_CeruleanCitySignText"] = "CELESTOPOLI\nUn'aura blu e\vmisteriosa la\vcirconda",
  ["_CeruleanCitySlowbroIgnoredOrdersText"] = "SLOWBRO ha\nignorato gli\vordini...",
  ["_CeruleanCitySlowbroIsLoafingAroundText"] = "SLOWBRO ciondola\nin giro...",
  ["_CeruleanCitySlowbroTookASnoozeText"] = "SLOWBRO si é fatto\nun sonnellino...",
  ["_CeruleanCitySlowbroTurnedAwayText"] = "SLOWBRO si é\ngirato dall'altra\vparte...",
  ["_CeruleanCitySuperNerd1Text"] = "Quel cespuglio\ndavanti al negozio\vé d'intralcio.\vForse c'é una via\valternativa.",
  ["_CeruleanCitySuperNerd2Text"] = "Stai facendo un\nenciclopedia sui\vPOKéMON?\vInteressante.",
  ["_CeruleanCitySuperNerd3Text"] = "Questa é la GROTTA\nCELESTE! Ci vivono\vPOKéMON\vfortissimi! Solo\vil campione della\vLEGA POKéMON puo'\ventrare!",
  ["_CeruleanCityTrainerTipsText"] = "CONSIGLI UTILI\nPremere il\vpulsante B durante\vl'evoluzione\vannulla l'intero\vprocesso.",
  ["_CeruleanGymAfterBattleText1"] = "Devi affrontare\naltri allenatori\vper scoprire\vquanto vali\vdavvero.",
  ["_CeruleanGymAfterBattleText2"] = "MISTY continuera'\na migliorare! Non\vperdera' con uno\vcome te!",
  ["_CeruleanGymBattleText1"] = "Valgo molto piu'\ndi te! MISTY puo'\vaspettare!",
  ["_CeruleanGymBattleText2"] = "Splash! Sono il\nprimo! Facciamolo!",
  ["_CeruleanGymEndBattleText1"] = "Mi hai\nsopraffatto!",
  ["_CeruleanGymEndBattleText2"] = "Non\npuo' essere!",
  ["_CeruleanGymGymGuideBeatMistyText"] = "Hai battuto MISTY!\nChe ti avevo\vdetto? Io e te,\vragazzo, siamo una\vbella squadra!",
  ["_CeruleanGymGymGuideChampInMakingText"] = "Ehi! Futuro\ncampione! Ecco il\vmio consiglio! La\vCAPOPALESTRA MISTY\vé un asso dei\vPOKéMON Acqua!\vPuoi prosciugarli\vcon i POKéMON\vPianta! O\vfulminarli con\vl'elettricita'!",
  ["_CeruleanGymMistyCascadeBadgeInfoText"] = "La MEDAGLIA\nCASCATA fa\vubbidire i POKéMON\vfino al Lv. 30!\vInclusi quelli\vscambiati! C'é di\vpiu': ora puoi\vusare TAGLIO! Puoi\vtagliare i piccoli\vcespugli per\vaprire vie! Prendi\vanche la mi MT\vpreferita!",
  ["_CeruleanGymMistyPreBattleText"] = "Ciao, sei una\nfaccia nuova! Gli\vallenatori che\vvogliono diventare\vpro devono avere\vuna politica sui\vPOKéMON! Qual é il\vtuo approccio\vquando catturi i\vPOKéMON? La mia\vpolitica é\vun'offensiva\vtotale con POKéMON\vAcqua!",
  ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "Acciderboli! Ci\nsai fare! Va bene!\vPrendi la MEDAGLIA\vCASCATA. per\vdimostrare che mi\vhai battuta!",
  ["_CeruleanGymMistyReceivedTM11Text"] = "{PLAYER} ha\nricevuto la MT11!",
  ["_CeruleanGymMistyTM11ExplanationText"] = "La MT11 insegna\nBOLLARAGGIO! Usala\vsu un POKéMON\vacquatico!",
  ["_CeruleanGymMistyTM11NoRoomText"] = "Faresti meglio a\nfare spazio!",
  ["_CeruleanMartCooltrainerFText"] = "Hai visto qualche\nCARAM. RARA?\vDovrebbe far\vsalire i POKéMON\vdi un livello!",
  ["_CeruleanMartCooltrainerMText"] = "Usa REPELLENTE per\ntenere insetti e\vPOKéM. deboli alla\vlarga. Metti il\vtuo POKéMON piu'\vforte in cima alla\vlista per\vrisultati\vottimali!",
  ["_CeruleanPokecenterGentlemanText"] = "Hai sentito\nparlare di BILL?\vTutti lo chiamano\vPOKéMANIAC! Penso\vche la gente sia\vsolo gelosa di\vBILL. Chi non\vvorrebbe vantarsi\vdei propri\vPOKéMON?",
  ["_CeruleanPokecenterGuyText"] = "BILL ha un sacco\ndi POKéMON!\vColleziona anche\vquelli rari!",
  ["_CeruleanPokecenterSuperNerdText"] = "Quel BILL! Ho\nsentito che fara'\vdi tutto per avere\vPOKéMON rari!",
  ["_CeruleanTradeHouseGrannyText"] = "A mio marito\npiacciono\vscambiare POKéMON.\vSe sei un\vcollezionista, ti\vandrebbe di\vscambiare con lui?",
  ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "Miserabili ROCKET!\nGuarda che cosa\vhanno combinato!\vHanno rubato una\vMT per insegnare a\vscavare a un\vPOKéMON! Mi é\vcostata un occhio\vdella testa!",
  ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "Quel che é perso,\né perso! Ho deciso\vdi insegnare a\vDIGLETT a scavare\vsenza MT!",
  ["_CeruleanTrashedHouseGirlText"] = "Il TEAM ROCKET\nstara' cercando di\vscavarsi un varco!",
  ["_CeruleanTrashedHouseWallHoleText"] = "Il TEAM ROCKET ha\nlasciato una via\vd'uscita!",
  ["_ChampionsRoomOakComeWithMeText"] = "OAK: {PLAYER}!\nCapisci che la tua\vvittoria non é\vdovuta solo a te!\vIl legame con i\vtuo POKéMON é\vmeraviglioso!\v{PLAYER}! Vieni con\vme!",
  ["_ChampionsRoomOakCongratulatesPlayerText"] = "OAK: Hai vinto!\nComplimenti! Sei\vil nuovo campione\vdella LEGA\vPOKéMON! Sei\vcresciuto molto da\vquando sei partito\vcon {RAM:wNameBuffer}!\v{PLAYER}, sei\vdiventato grande!",
  ["_ChampionsRoomOakDisappointedWithRivalText"] = "OAK: {RIVAL}! Sono\ndeluso! Sono\vvenuto quando ho\vsaputo che avevi\vbattuto i\vSUPERQUATTRO! Ma\vquando sono\varrivato, avevi\vgia' perso!\v{RIVAL}! Capisci\vperché hai perso?\vHai dimenticato di\vtratte i tuoi\vPOKéMON con amore\ve fiducia! Senza\vdi essi, non\vdiventerai mai un\vcampione!",
  ["_ChampionsRoomOakText"] = "OAK: {PLAYER}!",
  ["_ChampionsRoomRivalAfterBattleText"] = "Perché? Perché ho\nperso? Non ho mai\vcommesso errori\vcrescendo i miei\vPOKéMON...\vDannazione! Sei tu\vil nuovo campione\vdella LEGA\vPOKéMON! Anche se\vfaccio fatica ad\vammetterlo.",
  ["_ChampionsRoomRivalIntroText"] = "{RIVAL}: Ehi! Non\nvedevo l'ora di\vvederti, {PLAYER}!\vIl mio rivale deve\vessere forte!\vMentre completavo\vil POKéDEX, ho\vcercato ovunque\vPOKéMON forti! Non\vsolo, ho creato\vsquadre in grado\vdi battere ogni\vtipo! Ed ora! Sono\vil campione della\vLEGA POKéMON!\v{PLAYER}! Sai cosa\vsignifica? Te lo\vdico io! Sono\vl'allenatore piu'\vforte del mondo!",
  ["_ChargeMoveEffectText"] = "{USER}",
  ["_ChooseABoxText"] = "Scegli un BOX\nPOKéMON.",
  ["_CinnabarGymBlainePostBattleAdviceText"] = "FUOCOBOMBA é\nl'ultima tecnica\vdi fuoco! Non\vsprecarla sui\vPOKéMON Acqua!",
  ["_CinnabarGymBlainePreBattleText"] = "Ah! Sono BLAINE!\nSono il\vCAPOPALESTRA di\vISOLA CANNELLA! I\vmiei POKéMON di\vfuoco\vinceneriranno gli\vsfidanti! Ha!\vFaresti meglio\vavere\vANTISCOTTATURA!",
  ["_CinnabarGymBlaineReceivedTM38Text"] = "{PLAYER} ha\nricevuto\v{RAM:wStringBuffer}!",
  ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "Sono esaurito! Hai\nconquistato la\vMEDAGLIA VULCANO!",
  ["_CinnabarGymBlaineTM38ExplanationText"] = "La MT38 contiene\nFUOCOBOMBA!\vInsegnala ai\vPOKéMON di tipo\vFuoco! CHARMELEON\vo PONYTA sono\vottime scelte!",
  ["_CinnabarGymBlaineTM38NoRoomText"] = "Fai spazio per il\nmio regalo!",
  ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "Ah! La MEDAGLIA\nVULCANO accresce\vle abilita'\vSPECIALI dei\vPOKéMON! Tieni,\vpuoi avere anche\vquesto!",
  ["_CinnabarGymGymGuideBeatBlaineText"] = "{PLAYER}! Hai\nbattuto quel\vtestardo!",
  ["_CinnabarGymGymGuideChampInMakingText"] = "Ehi! Futuro\ncampione!\vL'irascibile\vBLAINE é un\vesperto di POKéM.\vFuoco! Spenta il\vsuo spirito con\vl'acqua! Meglio\vprendere delle\vANTISCOTTATURA!",
  ["_CinnabarGymQuizCorrectText"] = "Risposta esatta!\nAvanti, passa\vpure!",
  ["_CinnabarGymQuizIncorrectText"] = "Spiacente!\nSbagliato!",
  ["_CinnabarGymQuizIntroText"] = "Quiz sui POKéMON!\nRispondi bene e la\vporta si aprira'!\vSbaglia e dovrai\vaffrontare un\vallenatore! Se\vvuoi conservare i\vtuoi POKéMON per\vil CAPOPALESTRA...\vRispondi bene! Si\vcomincia!",
  ["_CinnabarGymSuperNerd1AfterBattleText"] = "Il fuoco, o per\nessere precisi, la\vcombustione...\vBlah, blah, blah,\vblah...",
  ["_CinnabarGymSuperNerd1BattleText"] = "Sai quanto puo'\nscaldarsi il fuoco\vdi un POKéMON?",
  ["_CinnabarGymSuperNerd1EndBattleText"] = "Urca!\nChe calore!",
  ["_CinnabarGymSuperNerd2AfterBattleText"] = "Non riesco a fare\na meno di rubare i\vPOKéMON altrui!",
  ["_CinnabarGymSuperNerd2BattleText"] = "Ero un ladro, ma\nho messo la testa\va posto come\vallenatore!",
  ["_CinnabarGymSuperNerd2EndBattleText"] = "Mi\narrendo!",
  ["_CinnabarGymSuperNerd3AfterBattleText"] = "Le mie teorie sono\ntroppo complesse\vper te!",
  ["_CinnabarGymSuperNerd3BattleText"] = "Non puoi vincere!\nHo studiato i\vPOKéMON a fondo!",
  ["_CinnabarGymSuperNerd3EndBattleText"] = "Waaa! I\nmiei studi!",
  ["_CinnabarGymSuperNerd4AfterBattleText"] = "Vorrei tanto che\nesistesse un\vPOKéMON ladro! Lo\vuserei!",
  ["_CinnabarGymSuperNerd4BattleText"] = "Adoro usare i\nPOKéMON di fuoco!",
  ["_CinnabarGymSuperNerd4EndBattleText"] = "Troppo\ncaldo da gestire!",
  ["_CinnabarGymSuperNerd5AfterBattleText"] = "BLAINE si era\nperso tra i monti\vquando apparve un\vPOKéMON volatile\vinfuocato. La sua\vluce aiuto' BLAINE\va trovare la via\vd'uscita!",
  ["_CinnabarGymSuperNerd5BattleText"] = "So perché BLAINE é\ndiventato\vallenatore!",
  ["_CinnabarGymSuperNerd5EndBattleText"] = "Ahi!",
  ["_CinnabarGymSuperNerd6AfterBattleText"] = "A noi fan dei\nPOKéM. Fuoco\vpiacciono PONYTA e\vNINETALES!",
  ["_CinnabarGymSuperNerd6BattleText"] = "Sono stato in\nmolte PALESTRE, ma\vquesta é la mia\vpreferita!",
  ["_CinnabarGymSuperNerd6EndBattleText"] = "Urca!\nTroppo caldo!",
  ["_CinnabarGymSuperNerd7AfterBattleText"] = "L'acqua batte il\nfuoco! Ma il fuoco\vscioglie il\vghiaccio!",
  ["_CinnabarGymSuperNerd7BattleText"] = "Il fuoco é debole\ncontro l'H2O!",
  ["_CinnabarGymSuperNerd7EndBattleText"] = "Oh!\nFiamma spenta!",
  ["_CinnabarIslandDoorIsLockedText"] = "La porta é chiusa\na chiave...",
  ["_CinnabarIslandGamblerText"] = "Gli scienziati\nfanno esperimenti\vnell'edificio\vbruciato.",
  ["_CinnabarIslandGirlText"] = "BLAINE della PAL.\ndi ISOLA CANNELLA\vé un tipo strano\vche vive qui da\vdecenni.",
  ["_CinnabarIslandGymSignText"] = "ISOLA CANNELLA\nPALESTRA POKéMON\vCAPOPALESTRA:\vBLAINE Il Mago dei\vQuiz Irascibile",
  ["_CinnabarIslandPokemonLabSignText"] = "LABORATORIO\nPOKéMON",
  ["_CinnabarIslandSignText"] = "ISOLA CANNELLA La\ncitta' ardente di\vpassione",
  ["_CinnabarLabFishingGuruText"] = "Qui studiamo a\nfondo i POKéMON.\vSpesso ci portano\vrari esemplari da\vesaminare.",
  ["_CinnabarLabFossilRoomScientist1ComeAgainText"] = "Aiyah! Sei\ntornato!",
  ["_CinnabarLabFossilRoomScientist1FossilIsBackToLifeText"] = "Dov'eri? Il tuo\nfossile é tornato\vin vita! Era\v{RAM:wStringBuffer} come\vpensavo!",
  ["_CinnabarLabFossilRoomScientist1GoForAWalkText"] = "Ci metto un po'!\nFatti una\vpasseggiata per un\vpo'!",
  ["_CinnabarLabFossilRoomScientist1GoForAWalkText2"] = "Ci metto un po'!\nFatti una\vpasseggiata per un\vpo'!",
  ["_CinnabarLabFossilRoomScientist1NoFossilsText"] = "No! Che peccato!",
  ["_CinnabarLabFossilRoomScientist1SeesFossilText"] = "Oh! Quello é\n{RAM:wNameBuffer}! é il\vfossile di\v{RAM:wStringBuffer}, un\vPOKéMON estinto!\vLa mia Macchina\vdella Resurrezione\vlo fara' rivivere!",
  ["_CinnabarLabFossilRoomScientist1TakesFossilText"] = "Allora sbrigati a\ndarmelo! {PLAYER}\vha consegnato\v{RAM:wNameBuffer}!",
  ["_CinnabarLabFossilRoomScientist1Text"] = "Ciao! Sono un\ndottore\vimportante! Studio\vrari fossili di\vPOKéMON! Tu! Hai\vun fossile per me?",
