  ["_CinnabarLabMetronomeRoomPCText"] = "C'é un messaggio\ne-mail! ... I 3\vuccelli POKéM.\vleggendari sono\vARTICUNO, ZAPDOS e\vMOLTRES. La loro\vposizione é\vsconosciuta.\vEsploreremo la\vgrotta vicina a\vCELESTOPOLI. Da:\vTEAM RICERCA\vPOKéMON ...",
  ["_CinnabarLabMetronomeRoomScientist1ReceivedTM35Text"] = "{PLAYER} ha\nricevuto\v{RAM:wStringBuffer}!",
  ["_CinnabarLabMetronomeRoomScientist1TM35ExplanationText"] = "Tch-tch-tch! é il\nsuono del\vMETRONOMO!\vStuzzica il\vcervello del\vPOKéMON facendogli\vusare mosse che\vnon conosce!",
  ["_CinnabarLabMetronomeRoomScientist1TM35NoRoomText"] = "Lo zaino é pieno\nzeppo!",
  ["_CinnabarLabMetronomeRoomScientist1Text"] = "Tch-tch-tch! Ho\ncreato una MT\vfiga! Puo'\vscatenare ogni\vgenere di\vdivertimento!",
  ["_CinnabarLabMetronomeRoomScientist2Text"] = "EEVEE puo'\nevolversi in 1 di\v3 specie di\vPOKéMON.",
