  ["_CinnabarPokecenterGentlemanText"] = "Hai amici? I\nPOKéMON ricevuti\vnegli scambi\vcrescono molto in\vfretta. Penso ne\vvalga la pena!",
  ["_CinnabarPokecenterGuyText"] = "I POKéMON possono\nancora imparare\vtecniche dopo aver\vannullato\vl'evoluzione.\vL'evoluzione puo'\vattendere nuove\vmosse.",
