  ["_CopycatsHouse1FMiddleAgedWomanText"] = "Mia figlia é cosi'\negotica. Ha solo\vpochi amici.",
  ["_CopycatsHouse2FCopycatDoYouLikePokemonText"] = "{PLAYER}: Ciao! Ti\npiacciono i\vPOKéMON? {PLAYER}:\vAh no, te l'ho\vappena chiesto.\v{PLAYER}: Eh? Sei\vstrana! MIMICA:\vMm? Smettere di\vimitare? Ma é il\vmio hobby\vpreferito!",
