  ["_CopycatsHouse2FCopycatTM31Explanation1Text"] = "La MT31 contiene\nla mia preferita,\vMIMICA! Usala su\vun buon POKéMON!",
  ["_CopycatsHouse2FCopycatTM31Explanation2Text"] = "{PLAYER}: Ciao!\nGrazie per la\vMT31! {PLAYER}:\vCome? {PLAYER}: é\vcosi' divertente\vimitare ogni mia\vmossa? MIMICA:\vGia'! é uno\vspasso!",
