  ["_FuchsiaBillsGrandpasHouseBillsGrandpaText"] = "Mh? Hai incontrato\nBILL? é mio\vnipote! Gli é\vsempre piaciuto\vcollezionare cose\vfin da piccolo!",
  ["_FuchsiaBillsGrandpasHouseMiddleAgedWomanText"] = "Il GUARDIANO é\nvecchio,\vma\arzillo! Ha\vtutti i denti\vfinti pero'.",
  ["_FuchsiaBillsGrandpasHouseYoungsterText"] = "BILL archivia i\nsuoi dati POKéMON\vsul suo PC! Te li\vha mostrati?",
  ["_FuchsiaCityChanseySignText"] = "Nome: CHANSEY\nCatturarne uno é\vsolo questione di\vfortuna.",
  ["_FuchsiaCityErikText"] = "ERIK: Dov'é SARA?\nHo detto che\vl'avrei incontrata\vqui.",
  ["_FuchsiaCityFossilSignKabutoText"] = "Nome: KABUTO Un\nPOKéMON\vresuscitato da un\vfossile.",
  ["_FuchsiaCityFossilSignOmanyteText"] = "Nome: OMANYTE Un\nPOKéMON\vresuscitato da un\vfossile.",
  ["_FuchsiaCityFossilSignUndeterminedText"] = "...",
  ["_FuchsiaCityGamblerText"] = "La ZONA SAFARI ha\nuno zoo\vall'ingresso. Sul\vretro c'é il GIOCO\vSAFARI per\vcatturare POKéMON.",
  ["_FuchsiaCityGymSignText"] = "FUCSIAPOLI\nPALESTRA POKéMON\vCAPOPALESTRA: KOGA\vIl Maestro Ninja\vVelenoso",
  ["_FuchsiaCityKangaskhanSignText"] = "Nome: KANGASKHAN\nUn POKéMON materno\vche alleva i\vpiccoli nel\vmarsupio sul\vventre.",
  ["_FuchsiaCityLaprasSignText"] = "Nome: LAPRAS Il re\ndei mari.",
  ["_FuchsiaCityPokecenterGuyText"] = "Se studi i\nPOKéMON, visita la\vZONA SAFARI. Ci\vsono ogni sorta di\vPOKéMON rari.",
  ["_FuchsiaCityPokemonText"] = "!",
  ["_FuchsiaCitySafariGameSignText"] = "GIOCO SAFARI\nCATTURA-POKéMON!",
  ["_FuchsiaCitySafariZoneSignText"] = "PARADISO POKéMON\nZONA SAFARI",
  ["_FuchsiaCitySignText"] = "FUCSIAPOLI Ecco il\nrosa passione!",
  ["_FuchsiaCitySlowpokeSignText"] = "Nome: SLOWPOKE\nAmichevole e molto\vlento nei\vmovimenti.",
  ["_FuchsiaCityVoltorbSignText"] = "Nome: VOLTORB\nL'esatta immagine\vdi una POKé BALL.",
  ["_FuchsiaCityWardensHomeSignText"] = "ZONA SAFARI CASA\nDEL GUARDIA",
  ["_FuchsiaCityYoungster1Text"] = "Hai provato il\nGIOCO SAFARI?\vAlcuni POKéMON si\vtrovano solo li'.",
  ["_FuchsiaCityYoungster2Text"] = "Quella Poké Ball\nper terra é in\vrealta' un\vPOKéMON.",
  ["_FuchsiaGoodRodHouseFishingGuruHowAreTheFishText"] = "Salve, {PLAYER}!\nCome abboccano i\vpesci?",
  ["_FuchsiaGoodRodHouseFishingGuruNoRoomText"] = "Oh no! Non hai\nspazio per il mio\vregalo!",
  ["_FuchsiaGoodRodHouseFishingGuruReceivedGoodRodText"] = "Ottimo! Mi piace\nil tuo stile!\vPrendi questo e\vpesca, giovanotto!\v{PLAYER} ha\vricevuto un\v{RAM:wStringBuffer}!",
  ["_FuchsiaGoodRodHouseFishingGuruText"] = "Sono il fratello\nmaggiore del GURU\vPESCATORE! Adoro\vletteralmente\vpescare! Ti piace\vpescare?",
  ["_FuchsiaGoodRodHouseFishingGuruThatsSoDisappointingText"] = "Oh... Che\ndelusione...",
  ["_FuchsiaGymGymGuideBeatKogaText"] = "é incredibile come\ni ninja\vterrorizzino\vancora oggi!",
  ["_FuchsiaGymGymGuideChampInMakingText"] = "Ehi! Futuro\ncampione! La\vPALESTRA DI\vFUCSIAPOLI é un\vlabirinto di muri\vinvisibili! KOGA\vsembra vicino, ma\vé bloccato! Devi\vtrovare i varchi\vnei muri per\vraggiungerlo!",
  ["_FuchsiaGymKogaBeforeBattleText"] = "KOGA: Fwahahaha!\nUn semplice\vbambino come te\vosa sfidarmi?\vMolto bene, ti\vmostrero' il\vterrore di un\vmaestro ninja!\vProverai la\vdisperazione di\vveleno e sonno!",
  ["_FuchsiaGymKogaPostBattleAdviceText"] = "Se colpiti da\nTOSSINA, i POKéMON\vsoffrono sempre\vpiu' con\vl'avanzare della\vlotta!\vTerrorizzera' di\vcerto i nemici!",
  ["_FuchsiaGymKogaReceivedSoulBadgeText"] = "Uhm! Hai\ndimostrato il tuo\vvalore! Tieni!\vPrendi la MEDAGLIA\vANIMA!",
  ["_FuchsiaGymKogaReceivedTM06Text"] = "{PLAYER} ha\nricevuto\v{RAM:wStringBuffer}!",
  ["_FuchsiaGymKogaSoulBadgeInfoText"] = "Ora che possiedi\nla MEDAGLIA ANIMA,\vla DIFESA dei tuoi\vPOKéMON aumenta!\vTi permette anche\vdi usare SURF\vfuori dallotta!\vAh, prendi anche\vquesto!",
  ["_FuchsiaGymKogaTM06ExplanationText"] = "La MT06 contiene\nTOSSINA! é una\vtecnica segreta\vvecchia di oltre\v400 anni!",
  ["_FuchsiaGymKogaTM06NoRoomText"] = "Fa' spazio per\nquesto, ragazzo!",
  ["_FuchsiaGymRocker1AfterBattleText"] = "Quindi unisci la\nforza all'ingegno?\vBuona strategia!",
  ["_FuchsiaGymRocker1BattleText"] = "La forza non é il\nfattore chiave per\vi POKéMON! é la\vstrategia! Ti\vmostrero' come\vbattere la forza\vbruta!",
  ["_FuchsiaGymRocker1EndBattleText"] = "Cosa?\nStraordinario!",
  ["_FuchsiaGymRocker2AfterBattleText"] = "Continuero' ad\nallenarmi sotto\vKOGA, il mio\vmaestro ninja!",
  ["_FuchsiaGymRocker2BattleText"] = "Volevo diventare\nun ninja, cosi'\vsono entrato in\vPALESTRA!",
  ["_FuchsiaGymRocker2EndBattleText"] = "Sono\nfritto!",
  ["_FuchsiaGymRocker3AfterBattleText"] = "Adoro veleno e\ntecniche di sonno,\vperché persistono\vdopo la lotta!",
  ["_FuchsiaGymRocker3BattleText"] = "Vediamo se batti\nle mie tecniche\vspeciali!",
  ["_FuchsiaGymRocker3EndBattleText"] = "Mi hai\ningannato!",
  ["_FuchsiaGymRocker4AfterBattleText"] = "Mi hai\nimpressionato!\vEcco un indizio!\vCerca con\vattenzione i\vvarchi nei muri\vinvisibili!",
  ["_FuchsiaGymRocker4BattleText"] = "Fermati li'! I\nnostri muri\vinvisibili ti\vfanno impazzire?",
