  ["_FuchsiaPokecenterCooltrainerFText"] = "C'é uno stretto\nsentiero a ovest\vdi SMERALDOPOLI.\vPorta al quartier\vgenerale della\vLEGA. Il Q.G.\vgoverna tutti gli\vallenatori.",
