  ["_IndigoPlateauLobbyCooltrainerFText"] = "Da qui in poi,\naffronterai i\vSUPER QUATTRO uno\va uno! Se vinci,\vsi apre la porta\vper il successivo!\vBuona fortuna!",
  ["_IndigoPlateauLobbyGymGuideText"] = "Ehila'! Campione\nin erba! Alla LEGA\vPOKéMON devi\vaffrontare i SUPER\vQUATTRO. Se perdi,\vricominci da capo!\vCi siamo! Dacci\vdentro!",
  ["_IndigoPlateauStatuesText1"] = "ALTOPIANO INDACO",
