  ["_JustAMomentText"] = "Un momento.",
  ["_KabutopsFossilText"] = "Fossile KABUTOPS\nUn POKéMON\vprimitivo e raro.",
  ["_KeptGoingAndCrashedText"] = "{USER} continua e\nsi schianta!",
  ["_LancesRoomLanceAfterBattleText"] = "Non posso ancora\ncredere che i miei\vdraghi abbiano\vperso, {PLAYER}!\vOra sei tu il\vcampione della\vLEGA POKéMON! O\vmeglio, lo saresti\vse non avessi un\vultimo ostacolo.\vDevi affrontare un\valtro allenatore!\vIl suo nome é...\v{RIVAL}! Ha\vbattuto i SUPER\vQUATTRO prima di\vte! é lui il vero\vcampione della\vLEGA POKéMON!",
  ["_LancesRoomLanceBeforeBattleText"] = "Ah! Ho sentito\nparlare di te! Io\vsono il capo dei\vSUPER QUATTRO! Mi\vchiamo LANCE e\vaddestro draghi!\vSai che i draghi\vsono POKéMON\vmitologici! Sono\vdifficili da\vcatturare, ma la\vloro potenza é\vsuperiore! Sono\vpraticamente\vindistruttibili!\vBene, pronto a\vperdere? La tua\vsfida finisce qui,\v{PLAYER}!",
  ["_LancesRoomLanceEndBattleText"] = "Basta! Odio\nammetterlo, ma sei\vun maestro di\vPOKéMON!",
  ["_LavenderCuboneHouseBrunetteGirlGhostIsGoneText"] = "Il FANTASMA della\nTORRE POKéMON é\vsparito! Qualcuno\vdeve aver placato\vla sua anima\virrequieta!",
  ["_LavenderCuboneHouseBrunetteGirlPoorCubonesMotherText"] = "Odio quei orribili\nROCKET! La madre\vdi quel povero\vCUBONE... é stata\vuccisa cercando di\vfuggire dal TEAM!",
  ["_LavenderCuboneHouseCuboneText"] = "CUBONE: Kyarugoo!",
  ["_LavenderMartBaldingGuyText"] = "Cerco strumenti\nche aumentano le\vabilita' dei\vPOKéMON durante\vuna lotta. ATTACCO\vX, DIFESA X,\vVELOCITA' X e\vSPECIAL X. Sai\vdove trovarli?",
  ["_LavenderMartCooltrainerMNuggetText"] = "Ho trovato una\nPEPITA sui monti.\vPensavo fosse\vinutile, ma l'ho\vvenduta a ¥5000!",
  ["_LavenderMartCooltrainerMReviveText"] = "Conosci\nREVITALIZ.?\vRivitalizza\vqualsiasi POKéMON\vesausto!",
  ["_LavenderPokecenterGentlemanText"] = "Il TEAM ROCKET\nfarebbe di tutto\vper il denaro!",
  ["_LavenderPokecenterGuyText"] = "I CUBONE portano i\nteschi, vero? La\vgente li paga\vmolto!",
  ["_LavenderPokecenterLittleGirlText"] = "Ho visto la madre\ndi CUBONE morire\vsfuggendo al TEAM\vROCKET!",
  ["_LavenderTownCooltrainerMText"] = "Questa citta' é\nnota come il\vcimitero dei\vPOKéMON. Si\vtengono\vcommemorazioni\vnella TORRE.",
  ["_LavenderTownLittleGirlDoYouBelieveInGhostsText"] = "Credi nei\nFANTASMI?",
  ["_LavenderTownLittleGirlHaHaGuessNotText"] = "Ahahah, immagino\ndi no. Quella mano\vbianca sulla tua\vspalla, non é\vvera.",
