  ["_MtMoon1FCooltrainerF1EndBattleText"] = "Oh!\nHo perso!",
  ["_MtMoon1FCooltrainerF2AfterBattleText"] = "Ho sentito che ci\nsono fossili molto\vrari qui.",
  ["_MtMoon1FCooltrainerF2BattleText"] = "Cosa? Aspetto i\nmiei amici qui.",
  ["_MtMoon1FCooltrainerF2EndBattleText"] = "Ho\nperso?",
  ["_MtMoon1FHikerAfterBattleText"] = "I ragazzi come te\nnon dovrebbero\vstare qui!",
  ["_MtMoon1FHikerBattleText"] = "UAU! Mi hai\nspaventato! Ah,\vsei solo un\vragazzo!",
  ["_MtMoon1FHikerEndBattleText"] = "\nAcciderboli!\vSpaventato di\vnuovo!",
  ["_MtMoon1FSuperNerdAfterBattleText"] = "Devo trovare\nPOKéMON piu'\vforti.",
  ["_MtMoon1FSuperNerdBattleText"] = "Cosa! Non\nprendermi alle\vspalle!",
  ["_MtMoon1FSuperNerdEndBattleText"] = "Il mio\nPOKéMON non basta!",
  ["_MtMoon1FYoungster1AfterBattleText"] = "Sono venuto qui\nper fare il bullo\vcon le ragazze.",
  ["_MtMoon1FYoungster1BattleText"] = "Sei venuto anche\ntu a esplorare?",
  ["_MtMoon1FYoungster1EndBattleText"] = "Perdere é\nuno schifo!",
  ["_MtMoon1FYoungster2AfterBattleText"] = "Li ho visti! Sono\nsicuro siano del\vTEAM ROCKET!",
  ["_MtMoon1FYoungster2BattleText"] = "Uomini sospetti\nnella grotta. E\vtu?",
  ["_MtMoon1FYoungster2EndBattleText"] = "Mi hai\npreso!",
  ["_MtMoon1FYoungster3AfterBattleText"] = "ZUBAT é tosto! Ma\npuo' essere utile\vse ne catturi uno.",
  ["_MtMoon1FYoungster3BattleText"] = "Attraversa la\ngrotta per\varrivare a\vCELESTOPOLI!",
  ["_MtMoon1FYoungster3EndBattleText"] = "Ho perso.",
  ["_MtMoonB2FDomeFossilYouWantText"] = "Vuoi il Fossile\nDome?",
  ["_MtMoonB2FHelixFossilYouWantText"] = "Vuoi il Fossile\nHelix?",
  ["_MtMoonB2FReceivedFossilText"] = "{PLAYER} ottiene\n{RAM:wStringBuffer}!",
  ["_MtMoonB2FRocket1AfterBattleText"] = "Mi hai fatto\narrabbiare! Il\vTEAM ti mettera'\val bando!",
  ["_MtMoonB2FRocket1BattleText"] = "Il TEAM ROCKET\ntrovera' i\vfossili, li\vrivendera' per\vfare soldi!",
  ["_MtMoonB2FRocket1EndBattleText"] = "Argh! Ora\nsono furioso!",
  ["_MtMoonB2FRocket2AfterBattleText"] = "Mannaggia! I miei\nsoci non la\vpasseranno liscia!",
  ["_MtMoonB2FRocket2BattleText"] = "Noi del TEAM\nROCKET siamo\vgangster POKéMON!",
  ["_MtMoonB2FRocket2EndBattleText"] = "Ho\nrovinato tutto!",
  ["_MtMoonB2FRocket3AfterBattleText"] = "Se trovi un\nfossile, dammelo e\vsparisci!",
  ["_MtMoonB2FRocket3BattleText"] = "Facciamo un affare\ngrosso qui!\vSparisci,\vmoccioso!",
  ["_MtMoonB2FRocket3EndBattleText"] = "Vedo che\nsei bravo.",
  ["_MtMoonB2FRocket4AfterBattleText"] = "I POKéMON vivevano\nqui molto prima\vdell'uomo.",
  ["_MtMoonB2FRocket4BattleText"] = "I bambini non\ndovrebbero seccare\vgli adulti!",
  ["_MtMoonB2FRocket4EndBattleText"] = "Che\nrabbia!",
  ["_MtMoonB2FSuperNerdOkIllShareText"] = "Va bene! Lo\ndivideremo!",
  ["_MtMoonB2FSuperNerdThenThisIsMineText"] = "D'accordo. Allora\nquesto é mio!",
  ["_MtMoonB2FSuperNerdTheresAPokemonLabText"] = "Lontano, all'ISOLA\nCANNELLA, c'é un\vLABORATORIO\vPOKéMON. Studiano\vla rigenerazione\vdei fossili.",
  ["_MtMoonB2FSuperNerdTheyreBothMineText"] = "Ehi, ferma! Li ho\ntrovati io! Sono\ventrambi miei!",
  ["_MtMoonB2FYouHaveNoRoomText"] = "Senti, non hai\nspazio per questo.",
  ["_MtMoonB2fSuperNerdEachTakeOneText"] = "Ne prendiamo uno a\ntesta! Niente\vingordigia!",
  ["_MtMoonPokecenterBenchGuyText"] = "Se hai troppi\nPOKéMON, puoi\vdepositarli al PC!",
  ["_MtMoonPokecenterGentlemanText"] = "Il TEAM ROCKET\nattacca i\vcittadini di\vCELESTOPOLI... Il\vTEAM ROCKET é\vsempre in prima\vpagina!",
  ["_MtMoonPokecenterMagikarpSalesmanIGotADealText"] = "UOMO: Salve! Ho un\naffare proprio per\vte! Ti do un\vmagnifico MAGIKARP\vper soli ¥500! Che\vne dici?",
  ["_MtMoonPokecenterMagikarpSalesmanNoMoneyText"] = "Ti servono piu'\nsoldi di cosi'!",
  ["_MtMoonPokecenterMagikarpSalesmanNoRefundsText"] = "UOMO: Be', io non\nfaccio rimborsi!",
  ["_MtMoonPokecenterMagikarpSalesmanNoText"] = "No? Lo faccio solo\ncome favore per\vte!",
  ["_MtMoonPokecenterYoungsterText"] = "Ho 6 POKé BALL\npronte alla\vcintura. Al\vmassimo puoi\vportare 6 POKéMON.",
  ["_MultiHitText"] = "Colpisce il nemico\n{NUM:wPlayerNumHits,\v1, 1} volte!",
  ["_Museum1FGamblerText"] = "Questo é un\nmagnifico fossile!",
  ["_Museum1FOldAmberText"] = "L'AMBRA é lucida e\ndorata!",
  ["_Museum1FScientist1AmberIsFossilizedTreeSapText"] = "L'AMBRA é linfa\nd'albero fossile.",
  ["_Museum1FScientist1ComeAgainText"] = "Torna presto!",
  ["_Museum1FScientist1DoYouKnowWhatAmberIsText"] = "Non puoi\nintrufolarti dal\vretro! Oh,\vinsomma! Sai cos'é\vl'AMBRA?",
  ["_Museum1FScientist1DontHaveEnoughMoneyText"] = "Non hai abbastanza\nsoldi.",
  ["_Museum1FScientist1GoToOtherSideText"] = "Prego, passa\ndall'altra parte!",
  ["_Museum1FScientist1TakePlentyOfTimeText"] = "Prenditi tutto il\ntempo per vederlo!",
  ["_Museum1FScientist1ThankYouText"] = "Ecco, ¥50! Grazie!",
  ["_Museum1FScientist1TheresALabSomewhereText"] = "C'é un laboratorio\nda qualche parte\vche cerca di\vresuscitare\vPOKéMON antichi\vdall'AMBRA.",
  ["_Museum1FScientist1WouldYouLikeToComeInText"] = "Il biglietto costa\n¥50 per i bambini.\vVuoi entrare?",
  ["_Museum1FScientist2GetTheOldAmberCheckText"] = "Ssh! Fai\nanalizzare l'AMBRA\vANTICA!",
  ["_Museum1FScientist2ReceivedOldAmberText"] = "{PLAYER} riceve\nAMBRA ANTICA!",
  ["_Museum1FScientist2TakeThisToAPokemonLabText"] = "Ssh! Credo che\nquesto pezzo di\vAMBRA contenga DNA\vdi POKéMON!\vSarebbe fantastico\vresuscitare un\vPOKéMON da esso!\vMa i miei colleghi\vmi ignorano!\vPercio' ho un\vfavore da\vchiederti: portalo\va un LABORATORIO\vPOKéMON!",
  ["_Museum1FScientist2YouDontHaveSpaceText"] = "Non hai spazio per\nquesto!",
  ["_Museum1FScientist3Text"] = "Siamo fieri di due\nfossili di\vrarissimi POKéMON\vpreistorici!",
  ["_Museum2FBrunetteGirlText"] = "Voglio un PIKACHU!\né cosi' carino! Ho\vchiesto a papa' di\vcatturarmene uno!",
  ["_Museum2FGrampsText"] = "20 luglio 1969! Il\n1° allunaggio! Ho\vcomprato una\vtelevisione a\vcolori per\vvederlo!",
  ["_Museum2FHikerText"] = "Si', un PIKACHU\narrivera' presto!",
  ["_Museum2FMoonStoneSignText"] = "Meteorite caduto\nnel MONTE LUNA.\v(PIETRALUNARE?)",
  ["_Museum2FScientistText"] = "Abbiamo una mostra\nspaziale in corso.",
  ["_Museum2FSpaceShuttleSignText"] = "NAVETTA SPAZIALE\nCOLUMBIA",
  ["_Museum2FYoungsterText"] = "PIETRALUNARE? Cosa\nc'é di cosi'\vspeciale?",
  ["_MustRechargeText"] = "{USER} deve\nricaricarsi!",
  ["_NameRatersHouseNameRaterATrulyImpeccableNameText"] = "{RAM:wNameBuffer}, eh? é\nun nome davvero\vimpeccabile! Abbi\vcura di\v{RAM:wNameBuffer}!",
  ["_NameRatersHouseNameRaterComeAnyTimeYouLikeText"] = "Va bene! Torna\nquando vuoi!",
  ["_NameRatersHouseNameRaterGiveItANiceNameText"] = "{RAM:wNameBuffer}, eh? é\nun soprannome\vdecente! Ma vuoi\vche gli dia un\vnome piu' carino?\vChe ne pensi?",
  ["_NameRatersHouseNameRaterPokemonHasBeenRenamedText"] = "Ok! Questo POKéMON\nora si chiama\v{RAM:wBuffer}! é un\vnome migliore di\vprima!",
  ["_NameRatersHouseNameRaterWantMeToRateText"] = "Salve, salve! Sono\nil GIUDICE\vONORARIO! Vuoi che\vvaluti i\vsoprannomi dei\vtuoi POKéMON?",
  ["_NameRatersHouseNameRaterWhatShouldWeNameItText"] = "Va bene! Come lo\nchiamiamo?",
  ["_NameRatersHouseNameRaterWhichPokemonText"] = "Quale POKéMON deve\nessere esaminato?",
  ["_NeedYourPokemonText"] = "Ok. Ci serve il\ntuo POKéMON.",
  ["_NewBadgeRequiredText"] = "No! Serve una\nnuova MEDAGLIA.",
  ["_NewBicycleText"] = "Una nuova e\nlucente\vBICICLETTA!",
  ["_NoCyclingAllowedHereText"] = "Qui non si puo'\nusare la bici.",
  ["_NoEffectText"] = "Non ha effetto!",
  ["_NoMonText"] = "Cosa? Non ci sono\nPOKéMON qui!",
  ["_NoMoreRoomForItemText"] = "Spazio esaurito\nper gli strumenti!",
  ["_NoMovesLeftText"] = "{RAM:wBattleMonNick} non ha\npiu' mosse!",
  ["_NoNibbleText"] = "Neanche\nun'abboccata!",
  ["_NoRoomToStoreText"] = "Nessun spazio per\ndepositare\vstrumenti.",
  ["_NoRunningText"] = "No! Non si puo'\nfuggire da una\vlotta fra\vallenatori!",
  ["_NoSurfingHereText"] = "Non si puo' USARE\nSURF su {RAM:wNameBuffer}\vqui!",
  ["_NoTrade1Text"] = "Uffa! Vabbé...",
  ["_NoTrade2Text"] = "Be', se non lo\nvuoi tu...",
  ["_NoTrade3Text"] = "Che peccato.",
  ["_NoWillText"] = "Manca la voglia di\ncombattere!",
  ["_NotEnoughCoinsSlotMachineText"] = "Gettoni\ninsufficienti!",
  ["_NotHealthyEnoughText"] = "Non é abbastanza\nsalutare.",
  ["_NotThisTimeText"] = "Non questa volta!",
  ["_NotVeryEffectiveText"] = "Non é molto\nefficace...",
  ["_NothingHappenedText"] = "Non é accaduto\nnulla!",
  ["_NothingHereText"] = "Sembra che non ci\nsia nulla.",
  ["_NothingStoredText"] = "Non c'é nulla\ndepositato.",
  ["_NothingToCutText"] = "Non c'é nulla da\nTAGLIARE!",
  ["_NothingToDepositText"] = "Non hai nulla da\ndepositare.",
  ["_OHKOText"] = "KO in un colpo!",
  ["_OKExclamationText"] = "OK!",
  ["_OakLabEmailText"] = "C'é un messaggio\ndi posta qui! ...\vChiamata a tutti\vgli allenatori di\vPOKéMON! I\vmigliori della\vLEGA POKéMON sono\vpronti a sfidare\vchiunque! Porta i\vtuoi migliori\vPOKéMON e scopri\vil tuo livello!\vSEDE LEGA POKéMON\vALTOPIANO INDACO\vPS: PROF. OAK,\vpassa a trovarci!\v...",
  ["_OakSpeechText1"] = "Salve! Benvenuto\nnel mondo dei\vPOKéMON! Mi chiamo\vOAK! Per tutti\vsono il PROF.\vPOKéMON!",
  ["_OakSpeechText2A"] = "Questo mondo é\ninabitato da\vcreature dette\vPOKéMON!",
  ["_OakSpeechText2B"] = "Per alcuni i\nPOKéMON sono\vanimali domestici.\vAltri li usano per\vlottare. Io...\vStudio i POKéMON\vcome professione.",
  ["_OakSpeechText3"] = "{PLAYER}! La tua\nleggenda sta per\viniziare! Un mondo\vdi sogni e\vavventure ti\vattende con i\vPOKéMON! Andiamo!",
  ["_OaksAideComeBackText"] = "Oh, capisco.\nQuando avrai\v{NUM:hOaksAideRequirement,\v1, 3} specie,\vtorna a prendere\v{RAM:wOaksAideRewardItemName}.",
  ["_OaksAideGotItemText"] = "{PLAYER} ottiene\n{RAM:wOaksAideRewardItemName}!",
  ["_OaksAideHereYouGoText"] = "Ottimo! Hai\ncatturato\v{NUM:hOaksAideNumMonsOwned,\v1, 3} specie di\vPOKéMON!\vComplimenti! Ecco\va te!",
  ["_OaksAideHiText"] = "Ciao! Ti ricordi\ndi me? Sono\vl'AIUTO del PROF.\vOAK! Se hai\vcatturato\v{NUM:hOaksAideRequirement,\v1, 3} specie di\vPOKéMON, dovrei\vdarti {RAM:wOaksAideRewardItemName}!\vAllora, {PLAYER}!\vHai catturato\valmeno\v{NUM:hOaksAideRequirement,\v1, 3} specie?",
  ["_OaksAideNoRoomText"] = "Oh! Vedo che non\nhai alcuno spazio\vper {RAM:wOaksAideRewardItemName}.",
  ["_OaksAideUhOhText"] = "Vediamo... Oh no!\nHai catturato solo\v{NUM:hOaksAideNumMonsOwned,\v1, 3} specie! Te\vne servono\v{NUM:hOaksAideRequirement,\v1, 3} per avere\v{RAM:wOaksAideRewardItemName}.",
  ["_OaksLabGirlText"] = "Il PROF. OAK é la\nmassima autorita'\vsui POKéMON! Molto\vallenatori lo\vstimano molto!",
  ["_OaksLabGivePokeballsExplanationText"] = "Quando appare un\nPOKéMON selvatico,\vé tutto valido.\vLancia una POKé\vBALL e prova a\vcatturarlo! Non\vfunziona sempre,\vpero'. Un POKéMON\vin salute puo'\vfuggire. Ci vuole\vfortuna!",
  ["_OaksLabLastMonText"] = "Questo é l'ultimo\nPOKéMON di OAK!",
  ["_OaksLabMonEnergeticText"] = "Questo POKéMON é\ndavvero pieno di\venergia!",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "OAK: Vieni a\ntrovarmi a volte.\vVoglio sapere come\vprocede il tuo\vPOKéDEX.",
  ["_OaksLabOak1DeliverParcelText"] = "OAK: Oh, {PLAYER}!\nCome sta il mio\vvecchio POKéMON?\vBe', sembra\vproprio che ti\vpiaccia. Devi\vavere un taleento\vcome allenatore!\vCosa? Hai qualcosa\vper me? {PLAYER}\vconsegna il PACCO\vdi OAK.",
  ["_OaksLabOak1HowIsYourPokedexComingText"] = "OAK: Che bello\nvederti! Come va\vil POKéDEX? Fammi\vdare un'occhiata!",
  ["_OaksLabOak1ParcelThanksText"] = "Ah! é la POKé BALL\npersonalizzata che\vho ordinato!\vGrazie!",
  ["_OaksLabOak1PokemonAroundTheWorldText"] = "I POKéMON di tutto\nil mondo ti\vattendono,\v{PLAYER}!",
  ["_OaksLabOak1RaiseYourYoungPokemonText"] = "OAK: {PLAYER},\ncresci il tuo\vgiovane POKéMON\vfacendolo lottare!",
  ["_OaksLabOak1ReceivedPokeballsText"] = "OAK: Non puoi\navere dati\vdettagliati\vvedendoli e basta.\vDevi catturarli!\vUsa questi per i\vPOKéMON selvatici.\v{PLAYER} riceve 5\vPOKé BALL!",
  ["_OaksLabOak1WhichPokemonDoYouWantText"] = "OAK: Dunque,\n{PLAYER}, quale\vPOKéMON vuoi?",
  ["_OaksLabOak1YourPokemonCanFightText"] = "OAK: Se appare un\nPOKéMON selvatico,\vil tuo puo'\vlottare contro di\vesso!",
  ["_OaksLabOak2Text"] = "?",
  ["_OaksLabOakBePatientText"] = "OAK: Pazienza!\nAnche {RIVAL} ne\vavra' uno!",
  ["_OaksLabOakChooseMonText"] = "OAK: {RIVAL}?\nLasciami\vpensare... Ah, é\vvero, ti avevo\vdetto di venire!\vAspetta! Ecco,\v{PLAYER}! Ci sono 3\vPOKéMON! Haha!\vSono dentro le\vPOKé BALL. Ero un\vserio allenatore\vda giovane! Alla\vmia eta' me ne\vrestano 3, ma uno\vé tuo! Scegli!",
  ["_OaksLabOakDontGoAwayYetText"] = "OAK: Ehi! Non te\nne andare ancora!",
  ["_OaksLabOakGotPokedexText"] = "OAK: {PLAYER} e\n{RIVAL}! Prendete\vquesti! {PLAYER}\vriceve il POKéDEX\vda OAK!",
  ["_OaksLabOakIHaveARequestText"] = "OAK: Ah, giusto!\nHo una richiesta\vper voi due.",
  ["_OaksLabOakMyInventionPokedexText"] = "Sulla scrivania\nc'é la mia\vinvenzione, il\vPOKéDEX! Registra\vin automatico i\vdati dei POKéMON\vvisti o catturati!\vé un'enciclopedia\vhi-tech!",
  ["_OaksLabOakThatWasMyDreamText"] = "Creare una guida\ncompleta di tutti\vi POKéMON...\vQuesto era il\vsogno mio! Ma sono\vtroppo vecchio!\vVoglio che voi due\vrealizziate il mio\vsogno! Forza,\vmuovetevi! Questa\vé una grande\vimpresa!",
  ["_OaksLabPokedexText"] = "é un'enciclopedia,\nma le pagine sono\vbianche!",
  ["_OaksLabReceivedMonText"] = "{PLAYER} riceve un\n{RAM:wNameBuffer}!",
  ["_OaksLabRivalAmIGreatOrWhatText"] = "{RIVAL}: Si'! Non\nsono fantastico?",
  ["_OaksLabRivalFedUpWithWaitingText"] = "{RIVAL}: Nonno!\nSono stufo di\vaspettare!",
  ["_OaksLabRivalGoAheadAndChooseText"] = "{RIVAL}: Heh, non\nho bisogno di fare\vl'avido come te!\vScegli pure,\v{PLAYER}!",
  ["_OaksLabRivalGrampsIsntAroundText"] = "{RIVAL}: Ehi\n{PLAYER}! Il nonno\vnon c'é!",
  ["_OaksLabRivalGrampsText"] = "{RIVAL}: Nonno!",
  ["_OaksLabRivalIPickedTheWrongPokemonText"] = "COSA? Incredibile!\nHo scelto il\vPOKéMON sbagliato!",
  ["_OaksLabRivalIllTakeThisOneText"] = "{RIVAL}: Prendero'\nquesto, allora!",
  ["_OaksLabRivalIllTakeYouOnText"] = "{RIVAL}: Aspetta\n{PLAYER}! Vediamo i\vnostri POKéMON!\vForza, ti sfido!",
  ["_OaksLabRivalLeaveItAllToMeText"] = "{RIVAL}: D'accordo\nnonno! Faccio io!\v{PLAYER}, odio\vdirlo, ma non mi\vservi! Lo so!\vPrestero' una\vMAPPA CITTA' da\vmia sorella! Le\vdiro' di non\vdartela, {PLAYER}!\vAhahah!",
  ["_OaksLabRivalMyPokemonLooksStrongerText"] = "{RIVAL}: Il mio\nPOKéMON sembra\vmolto piu' forte.",
  ["_OaksLabRivalReceivedMonText"] = "{RIVAL} riceve un\n{RAM:wNameBuffer}!",
  ["_OaksLabRivalSmellYouLaterText"] = "{RIVAL}: Ok! Faro'\nlottare il mio\vPOKéMON per\vrinforzarlo!\v{PLAYER}! Nonno! A\vpresto!",
  ["_OaksLabRivalWhatAboutMeText"] = "{RIVAL}: Ehi!\nNonno! E io?",
  ["_OaksLabRivalWhatDidYouCallMeForText"] = "{RIVAL}: Perché mi\nhai chiamato?",
  ["_OaksLabScientistText"] = "Studio i POKéMON\ncome aiuto del\vPROF. OAK.",
  ["_OaksLabThoseArePokeBallsText"] = "Quelle sono POKé\nBALL. Contengono\vPOKéMON!",
  ["_OaksLabYouWantBulbasaurText"] = "Dunque! Vuoi il\nPOKéMON pianta,\vBULBASAUR?",
  ["_OaksLabYouWantCharmanderText"] = "Dunque! Vuoi il\nPOKéMON fuoco,\vCHARMANDER?",
  ["_OaksLabYouWantSquirtleText"] = "Dunque! Vuoi il\nPOKéMON acqua,\vSQUIRTLE?",
  ["_OhFineThenText"] = "Oh, va bene.",
  ["_OlderFileWillBeErasedText"] = "Il vecchio file\nsara' cancellato\vper salvare. OK?",
  ["_OnceReleasedText"] = "Una volta\nliberato,\v{RAM:wStringBuffer} é perso\vper sempre. OK?",
  ["_OneMoreGoSlotMachineText"] = "Un altro giro?",
  ["_OneTwoAndText"] = "1, 2 e...",
  ["_OopsYouDontHaveEnoughRoomText"] = "Ops! Non hai\nabbastanza spazio.",
  ["_OutOfCoinsSlotMachineText"] = "Acciderboli!\nGettoni esauriti!",
  ["_OutOfSafariBallsText"] = "PA: Din-don! Le\nSAFARI BALL sono\vfinite!",
  ["_PPIncreasedText"] = "I PP di {RAM:wStringBuffer}\naumentano.",
  ["_PPMaxedOutText"] = "I PP di {RAM:wStringBuffer}\nsono al massimo.",
  ["_PPRestoredText"] = "I PP sono stati\nripristinati.",
  ["_PalletTownFisherText"] = "La tecnologia é\nincredibile! Ora\vpuoi archiviare e\vrichiamare oggetti\ve POKéMON come\vdati via PC!",
  ["_PalletTownGirlText"] = "Allevo anch'io i\nPOKéMON! Quando\vsaranno forti,\vpotranno\vproteggermi!",
  ["_PalletTownOakHeyWaitDontGoOutText"] = "OAK: Ehi! Aspetta!\nNon uscire!",
  ["_PalletTownOakItsUnsafeText"] = "OAK: é pericoloso!\nI POKéMON\vselvatici vivono\vnell'erba! Ti\vserve un tuo\vPOKéMON per\vproteggerti. Lo\vso! Vieni con me!",
  ["_PalletTownOaksLabSignText"] = "LABORATORIO DI\nRICERCA POKéMON DI\vOAK",
  ["_PalletTownPlayersHouseSignText"] = "Casa di {PLAYER}",
  ["_PalletTownRivalsHouseSignText"] = "Casa di {RIVAL}",
  ["_PalletTownSignText"] = "BIANCAVILLA Le\nsfumature di un\vnuovo viaggio!",
  ["_ParalyzedMayNotAttackText"] = "{TARGET} é\nparalizzato! Puo'\vnon attaccare!",
  ["_ParlyzHealText"] = "La paralisi di\n{RAM:wNameBuffer}\vsvanisce!",
  ["_PartyMenuBattleText"] = "Quale POKéMON\nmandare in campo?",
  ["_PartyMenuItemUseText"] = "Usare lo strumento\nsu quale POKéMON?",
  ["_PartyMenuNormalText"] = "Scegli un POKéMON.",
  ["_PartyMenuSwapMonText"] = "Spostare il\nPOKéMON dove?",
  ["_PartyMenuUseTMText"] = "Usare la MT su\nquale POKéMON?",
  ["_PewterCityCooltrainerFText"] = "Si dice che i\nCLEFAIRY arrivino\vdalla luna! Sono\vapparsi dopo che\vla PIETRALUNARE é\vcaduta sul monte.",
  ["_PewterCityCooltrainerMText"] = "Non ci sono molti\nallenatori seri\vqui! Sono come\vPIGLIAMOSCHE, ma\vBROCK di PLUMOPOLI\vé davvero in\vgamba!",
  ["_PewterCityGymSignText"] = "PLUMOPOLI PALESTRA\nPOKéMON\vCAPOPALESTRA:\vBROCK Il roccioso\vallenatore\vPOKéMON!",
  ["_PewterCityMuseumSignText"] = "MUSEO DELLA\nSCIENZA DI\vPLUMOPOLI",
  ["_PewterCityPokecenterGuyText"] = "Yawn! Quando\nJIGGLYPUFF canta,\vi POKéMON si\vaddormentano...\v...Anche io...\vFiiu...",
  ["_PewterCityPoliceNoticeSignText"] = "AVVISO! Dei ladri\nrubano fossili\vPOKéMON al MONTE\vLUNA! Chiamate la\vpolizia per info!",
  ["_PewterCitySignText"] = "PLUMOPOLI La\ncitta' dal grigio\vroccioso",
  ["_PewterCitySuperNerd1DidYouCheckOutMuseumText"] = "Hai visitato il\nMUSEO?",
  ["_PewterCitySuperNerd1ItsRightHereText"] = "é proprio qui! Si\npaga per entrare,\vma ne vale la\vpena! Ci vediamo!",
  ["_PewterCitySuperNerd1WerentThoseFossilsAmazingText"] = "Non erano\nfantastici i\vfossili del MONTE\vLUNA?",
  ["_PewterCitySuperNerd1YouHaveToGoText"] = "Davvero? Devi\nassolutamente\vandarci!",
  ["_PewterCitySuperNerd2DoYouKnowWhatImDoingText"] = "Psssst! Sai cosa\nsto facendo?",
  ["_PewterCitySuperNerd2ImSprayingRepelText"] = "Spruzzo REPELLENTE\nper tenere i\vPOKéMON lontani\vdal giardino!",
  ["_PewterCitySuperNerd2ThatsRightText"] = "Esatto! é un duro\nlavoro!",
  ["_PewterCityTrainerTipsText"] = "CONSIGLI Ogni\nPOKéMON che prende\vparte alla lotta\vguadagna ESP!",
  ["_PewterCityYoungsterGoTakeOnBrockText"] = "Se hai stoffa, va'\na sfidare BROCK!",
  ["_PewterCityYoungsterYoureATrainerFollowMeText"] = "Sei un allenatore,\nvero? BROCK cerca\vnuovi sfidanti!\vSeguimi!",
  ["_PewterGymBrockBoulderBadgeInfoText"] = "Questa é una\nMEDAGLIA ufficiale\vdella LEGA\vPOKéMON! I POKéMON\vdi chi la possiede\vsono piu' forti!\vOra puoi usare\vFLASH in ogni\vmomento!",
  ["_PewterGymBrockPostBattleAdviceText"] = "Ci sono allenatori\ndi ogni tipo nel\vmondo! Sembri\vmolto dotato come\vallenatore\vPOKéMON! Vai alla\vPALESTRA di\vCELESTOPOLI a\vtestare le\vabilita'!",
  ["_PewterGymBrockPreBattleText"] = "Io sono BROCK!\nSono il\vCAPOPALESTRA di\vPLUMOPOLI! Credo\vin una difesa di\vroccia e nella\vdeterminazione!\vPercio' i miei\vPOKéMON sono tutti\vdi tipo roccia!\vVuoi ancora\vsfidarmi? Bene!\vMostrami il tuo\vmeglio!",
  ["_PewterGymBrockReceivedBoulderBadgeText"] = "Ti ho\nsottovalutato.\vCome prova della\vvittoria, ecco la\vMEDAGLIA SASSO!\v{PLAYER} riceve la\vMEDAGLIA SASSO!",
  ["_PewterGymBrockWaitTakeThisText"] = "Aspetta! Prendi\nquesto con te!",
  ["_PewterGymCooltrainerMAfterBattleText"] = "Sei forte, ma non\nquanto BROCK!",
  ["_PewterGymCooltrainerMBattleText"] = "Fermati li',\nragazzino! Sei\vancora a anni luce\vda BROCK!",
  ["_MisReadPlaceholder"] = "",
  ["_PewterGymCooltrainerMEndBattleText"] = "\nMaledizione! Anni\vluce mi separano\vda BROCK!",
  ["_PewterGymGuideAdviceText"] = "Il 1° POKéMON in\ncampo é in cima\valla LISTA\vPOKéMON! Cambiando\vl'ordine dei\vPOKéMON, le lotte\vsaranno piu'\vfacili!",
  ["_PewterGymGuideBeginAdviceText"] = "Bene! Diamo inizio\nallo spettacolo!",
  ["_PewterGymGuideFreeServiceText"] = "é un servizio\ngratuito! Diamo\vinizio alle danze!",
  ["_PewterGymGuidePostBattleText"] = "Proprio come\npensavo! Hai\vstoffa da\vcampione!",
  ["_PewterGymGuidePreAdviceText"] = "Ehila'! Si vede\nche hai la stoffa\vdel campione! Non\vsono un\vallenatore, ma so\vcome vincere! Ti\vportero' in alto!",
  ["_PewterGymReceivedTM34Text"] = "{PLAYER} riceve\nMT34!",
  ["_PewterGymTM34NoRoomText"] = "Non hai spazio per\nquesto!",
  ["_PewterMartSuperNerdText"] = "Cose buone possono\ncapitare se allevi\vcon diligenza i\vPOKéMON, anche\vquelli deboli!",
  ["_PewterMartYoungsterText"] = "Un vecchio losco\nmi ha fatto\vcomprare uno\vstrano POKéMON\vpesce! é\vdebolissimo e é\vcostato ¥500!",
  ["_PewterNidoranHouseLittleBoyText"] = "NIDORAN cuccia!",
  ["_PewterNidoranHouseMiddleAgedManText"] = "Il nostro POKéMON\nviene da uno\vscambio, é duro.\vUn forestiero é un\vPOKéMON preso\vtramite scambio.\vCresce in fretta,\vma puo' ignorare\vun allenatore\vinesperto in\vlotta! Se solo\vavessimo\vmedaglie...",
  ["_PewterNidoranHouseNidoranText"] = "NIDORAN: Bowbow!",
  ["_PewterPokecenterGentlemanText"] = "Cosa!? Il TEAM\nROCKET é al MONTE\vLUNA? Eh? Sono al\vtelefono!\vSparisci!",
  ["_PewterPokecenterJigglypuffText"] = "JIGGLYPUFF: Puu\npupuu!",
  ["_PewterSpeechHouseGamblerText"] = "I POKéMON imparano\nnuove tecniche\vcrescendo! Ma\valcune mosse vanno\vinsegnate\vdall'allenatore!",
  ["_PewterSpeechHouseYoungsterText"] = "I POKéMON sono\npiu' facili da\vcatturare se\vferiti o\vaddormentati! Ma\vnon é una certezza\vassoluta!",
  ["_PickUpPayDayMoneyText"] = "{PLAYER} raccoglie\n¥{NUM:wTotalPayDayMoney,\v3 | LEADING_ZEROES\v| LEFT_ALIGN}!",
  ["_PlaySlotMachineText"] = "Una slot machine!\nVuoi giocare?",
  ["_PlayedFluteHadEffectText"] = "{PLAYER} suona il\nFLAUTO POKéMON.",
  ["_PlayedFluteNoEffectText"] = "Suonato il FLAUTO\nPOKéMON. Che\vmotivetto\vorecchiabile!",
  ["_PlayerBlackedOutText"] = "{PLAYER} non ha\npiu' POKéMON\vvalidi! {PLAYER} é\vk.o.!",
  ["_PlayerBlackedOutText2"] = "{PLAYER} non ha\npiu' POKéMON\vvalidi! {PLAYER} é\vk.o.!",
