  ["_PotionText"] = "{RAM:wNameBuffer}\nrecupera\v{NUM:wHPBarHPDifference,\v2, 3}!",
  ["_PowerPlantVoltorbBattleText"] = "Bzzzt!",
  ["_PowerPlantZapdosBattleText"] = "Gyaoo!",
  ["_PushStartText"] = "Premi START per\naprire il MENU!",
  ["_RaisePPWhichTechniqueText"] = "Aumentare i PP di\nquale mossa?",
  ["_RanAwayScaredText"] = "{TARGET} é fuggito\nper la paura!",
  ["_RanFromBattleText"] = "{USER} fugge dalla\nlotta!",
  ["_RareCandyText"] = "{RAM:wNameBuffer} sale al\nlivello\v{NUM:wCurEnemyLevel,\v1, 3}!",
  ["_RedBedroomSNESText"] = "{PLAYER} gioca al\nSuper NES!\v...Bene! é ora di\vandare!",
  ["_RedsHouse1FMomLookingGreatText"] = "MAMMA: Oh bene! Tu\ne i POKéMON state\vbenissimo! Badate\va voi!",
  ["_RedsHouse1FMomWakeUpText"] = "MAMMA: Giusto.\nTutti i ragazzi\vlasciano casa. Lo\vhan detto in TV.\vIl PROF. OAK, qui\vaccanto, ti cerca.",
  ["_RedsHouse1FMomYouShouldRestText"] = "MAMMA: {PLAYER}!\nDovresti riposare\vun attimo.",
  ["_RedsHouse1FTVStandByMeMovieText"] = "C'é un film in TV.\nQuattro ragazzi\vcamminano sui\vbinari. Meglio\vandare anch'io.",
  ["_RedsHouse1FTVWrongSideText"] = "Ops, lato\nsbagliato.",
