  ["_TryingToLearnText"] = "{RAM:wLearnMoveMonName} prova a\nimparare\v{RAM:wStringBuffer}! Ma non\vpuo' cono scere\vpiu' di 4 mosse!\vCancellare una\vvecchia mossa per\v{RAM:wStringBuffer}?",
  ["_TurnPageText"] = "Giri pagina?",
  ["_TurnedAwayText"] = "{RAM:wBattleMonNick} si é\ntirato indietro!",
  ["_TurnedOnPC1Text"] = "{PLAYER} accende il\nPC.",
  ["_TurnedOnPC2Text"] = "{PLAYER} accende il\nPC.",
  ["_UnaffectedText"] = "{TARGET} non\nsubisce effetti!",
  ["_UndergroundPathRoute6GirlText"] = "La gente perde\nsempre cose in\vquel PASSAGGIO\vSOTTERRANEO.",
  ["_UndergroundPathRoute7CopyUnusedGirlText"] = "Voglio fare acqui\nsti al centro com\vmerciale ma... Ci\vsono troppe facce\vlosche li'.",
  ["_UndergroundPathRoute7CopyUnusedGoesUnderSaffronText"] = "Il PASSAGGIO passa\nsotto\vZAFFERANOPOLI e\vporta a\vLAVANDONIA. Per\vCELESTOPOLI, usa\vl'edificio\vdall'altra parte.",
  ["_UndergroundPathRoute7CopyUnusedMiddleAgedManText"] = "Vuoi fare acquisti\na AZZURROPOLI?\vEsci e vai a\vovest!",
  ["_UndergroundPathRoute7CopyUnusedTeamRocketHadAHideoutText"] = "Il TEAM ROCKET\naveva un covo a\vAZZURROPOLI?",
  ["_UndergroundPathRoute7MiddleAgedManText"] = "Ho sentito che un\nPOKéMON\vdormiglione é\vapparso a\vAZZURROPOLI.",
  ["_UndergroundPathRoute8GirlText"] = "Il centro\ncommerciale di\vAZZURROPOLI é\vfornitissimo!",
  ["_UnleashedEnergyText"] = "{USER} ha\nscatenato energia!",
  ["_UnusedBenchGuyText1"] = "Vorrei tanto cat\nturare POKéMON.",
  ["_UnusedBenchGuyText2"] = "Sono stanco di\ntutto questo\vsvago...",
  ["_UnusedBenchGuyText3"] = "Il manager SILPH é\nnascosto nel\vSAFARI.",
  ["_UnveiledGhostText"] = "La SONDA SILPH ha\nsvelato\vl'identita' del\vFANTASMA!",
  ["_UseNextMonText"] = "Usa il prossimo?",
  ["_UsedCutText"] = "{RAM:wNameBuffer} ha\ntranciato con\vTAGLIO!",
  ["_UsedInsteadText"] = "invece,",
  ["_UsedMove1Text"] = "usa",
  ["_UsedMove2Text"] = "usa",
  ["_UsedStrengthText"] = "{RAM:wNameBuffer} usa\nFORZA.",
  ["_VendingMachineText1"] = "Un distributore!\nEcco il menu!",
  ["_VendingMachineText4"] = "Ops, soldi\ninsufficienti!",
  ["_VendingMachineText5"] = "{RAM:wStringBuffer} é\nuscito!",
  ["_VendingMachineText6"] = "Non c'é piu'\nspazio per roba!",
  ["_VendingMachineText7"] = "Non ho sete!",
  ["_VermilionCityBeautyText"] = "Siamo attenti\nall'inquinamento!\vGRIMER si multi\vplica nel fango\vtossico!",
  ["_VermilionCityGambler1DidYouSeeText"] = "Hai visto la M/N\nANNA ormeggiata al\vporto?",
  ["_VermilionCityGambler1SSAnneDepartedText"] = "La M/N ANNA é\npartita! Tornera'\vtra circa un anno.",
  ["_VermilionCityGambler2Text"] = "Sto costruendo un\npalazzo qui. Il\vmio POKéMON sta\vspianando il\vsuolo.",
  ["_VermilionCityGymSignText"] = "PALESTRA POKéMON\ndi ARANCIOPOLI\vCAPOPALESTRA:\vLT.SURGE Il\vfulmine americano!",
  ["_VermilionCityHarborSignText"] = "PORTO DI\nARANCIOPOLI",
  ["_VermilionCityMachopStompingTheLandFlatText"] = "Un MACHOP sta\nspianando il\vterreno.",
  ["_VermilionCityMachopText"] = "MACHOP: Guoh!\nGogogoh!",
  ["_VermilionCityNoticeSignText"] = "AVVISO! Il\nPERCORSO 12 é\vbloccato da un\vPOKéMON\vaddormentato.\vDeviazione per il\vTUNNEL ROCCIOSO\vper LAVANDONIA.\vPOLIZIA\vARANCIOPOLI",
  ["_VermilionCityPokemonFanClubSignText"] = "FAN CLUB POKéMON\nBenvenuti fan dei\vPOKéMON!",
  ["_VermilionCitySailor1DoYouHaveATicketText"] = "Benvenuto sulla\nM/N ANNA! Scusa,\vhai un biglietto?",
  ["_VermilionCitySailor1FlashedTicketText"] = "{PLAYER} mostra il\nTICKET. Bene!\vBenvenuto sulla\vM/N ANNA!",
  ["_VermilionCitySailor1ShipSetSailText"] = "La nave é salpata.",
  ["_VermilionCitySailor1WelcomeToSSAnneText"] = "Benvenuto sulla\nM/N ANNA!",
  ["_VermilionCitySailor1YouNeedATicketText"] = "{PLAYER} non ha il\nnecessario TICKET.\vSpiacente! Serve\vun biglietto per\vsalire a bordo.",
  ["_VermilionCitySailor2Text"] = "La M/N ANNA é una\nlussuosa nave da\vcrociera.\vVisitiamo\vARANCIOPOLI una\vvolta l'anno.",
  ["_VermilionCitySignText"] = "ARANCIOPOLI Porto\ndei tramonti\vsquisiti",
  ["_VermilionGymGentlemanAfterBattleText"] = "La porta non si\napre? LT.SURGE é\vsempre stato\vprudente!",
  ["_VermilionGymGentlemanBattleText"] = "Ero nell'esercito,\ne LT.SURGE era il\vmio sergente!",
  ["_VermilionGymGentlemanEndBattleText"] = "Basta!\nSei bravissimo!",
  ["_VermilionGymGymGuideBeatLTSurgeText"] = "Uff! Quella lotta\nera elettrizzante!",
  ["_VermilionGymGymGuideChampInMakingText"] = "Ehila'! Campione!\nLT.SURGE ha un\vsoprannome: il\vFulmine Americano!\vé un esperto di\vPOKéMON elettro! I\vvolatili e l'acqua\vrischiano molto!\vAttento anche alla\vparalisi! LT.SURGE\vé molto cauto!\vDovrai violare un\vcodice per\varrivargli!",
  ["_VermilionGymLTSurgePostBattleAdviceText"] = "Un piccolo consi\nglio, ragazzo!\vL'elettricita' é\vpotente! Ma é\vinutile con i\vPOKéMON terra!",
  ["_VermilionGymLTSurgePreBattleText"] = "Ehi, ragazzo! Che\nfai qui? Non\vdurerai molto in\vcombattimento! Te\vlo assicuro! I\vPOKéMON elettro mi\vhanno salvato\vdurante la guerra!\vHanno fulminato i\vmiei nemici! Faro'\vlo stesso con te!",
  ["_VermilionGymLTSurgeReceivedTM24Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_VermilionGymLTSurgeReceivedThunderBadgeText"] = "Urca! Sei davvero\nin gamba, ragazzo!\vPrendi la MEDAGLIA\vTUONO!",
  ["_VermilionGymLTSurgeTM24NoRoomText"] = "Ragazzo, fai\nspazio nel tuo\vzaino!",
  ["_VermilionGymLTSurgeThunderBadgeInfoText"] = "La MEDAGLIA TUONO\naccende la\vVELOCITA' del tuo\vPOKéMON! Ti\vpermette anche di\vusare FLASH! Sei\vspeciale! Prendi\vquesto!",
  ["_VermilionGymSailorAfterBattleText"] = "LT.SURGE ha messo\ndue serrature! Un\vindizio! La\vseconda é sem pre\vvicina alla prima\vaperta!",
  ["_VermilionGymSailorBattleText"] = "Questo non é un\nposto per bambini!",
  ["_VermilionGymSailorEndBattleText"] = "Wow! Che\nsorpresa!",
  ["_VermilionGymSuperNerdAfterBattleText"] = "OK, parlo!\nLT.SURGE ha\vnascosto gli\vinterruttori\vdentro qualcosa!",
  ["_VermilionGymSuperNerdBattleText"] = "Sono un peso\nleggero, ma me la\vcavo con\vl'elettricita'",
  ["_VermilionGymSuperNerdEndBattleText"] = "\nFolgorato!",
  ["_VermilionGymTrashFailTest"] = "No! C'é solo\nspazzatura. Ehi!\vLe serrature\velettriche sono\vstate azzerate!",
  ["_VermilionGymTrashSuccessText1"] = "Ehi! C'é un\ninterruttore sotto\vla spazzatura!\vAttivalo! La 1ª\vserratura si é\vaperta!",
  ["_VermilionGymTrashSuccessText2"] = "Ehi! C'é un altro\ninterruttore sotto\vla spazzatura!\vAttivalo!",
  ["_VermilionGymTrashSuccessText3"] = "La 2ª serratura si\né aperta! La porta\vmotoriz zata si\vapre!",
  ["_VermilionGymTrashText"] = "No, c'é solo\nspazzatura qui.",
  ["_VermilionMartCooltrainerFText"] = "I POKéMON possono\nessere buoni o\vcattivi a seconda\vdell'allenatore.",
  ["_VermilionMartCooltrainerMText"] = "Ci sono persone\ncattive che usano\vi POKéMON per\vdelitti. Il TEAM\vROCKET tratta\vPOKéMON rari e\vabbandona quelli\vche non ritiene\vutili.",
  ["_VermilionOldRodHouseFishingGuruDoYouLikeToFishText"] = "Sono il GURU\nPESCATORE! Adoro\vpescare! Ti piace\vpescare?",
  ["_VermilionOldRodHouseFishingGuruFishingIsAWayOfLifeText"] = "La pesca é uno\nstile di vita! Dai\vmari ai fiumi,\vesci e prendi\vquello grosso!",
  ["_VermilionOldRodHouseFishingGuruHowAreTheFishBitingText"] = "Ciao, {PLAYER}!\nAboccano i pesci?",
  ["_VermilionOldRodHouseFishingGuruNoRoomText"] = "Oh no! Non hai\nspazio per il mio\vdono!",
  ["_VermilionOldRodHouseFishingGuruTakeThisText"] = "Ottimo! Mi piace\nil tuo stile!\vPrendi questo,\vgiovane! {PLAYER}\vriceve un\v{RAM:wStringBuffer}!",
  ["_VermilionOldRodHouseFishingGuruThatsSoDisappointingText"] = "Oh... Che delu\nsione...",
  ["_VermilionPidgeyHouseLetterText"] = "Cara PIPPI, spero\ndi vederti presto.\vHo sentito che\vZAFFERANOPOLI ha\vguai col TEAM\vROCKET.\vARANCIOPOLI sembra\vincolume.",
  ["_VermilionPidgeyHousePidgeyText"] = "PIDGEY: Kurukkoo!",
  ["_VermilionPidgeyHouseYoungsterText"] = "Mando il mio\nPIDGEY a portare\vuna lettera a\vZAFFERANOPOLI!",
  ["_VermilionPokecenterFishingGuruText"] = "Anche allo stesso\nlivello, i POKéMON\vhanno abilita'\vmolto diverse. Un\vPOKéMON alleva to\vé piu' forte di\vuno selvatico.",
  ["_VermilionPokecenterGuyText"] = "é vero che un\nlivello piu' alto\vrende piu'\vforte... Ma ogni\vPOKéMON ha punti\vdeboli verso altri\vtipi. Quindi non\vesiste il POKéMON\vasso assoluto.",
  ["_VermilionPokecenterSailorText"] = "Il mio POKéMON era\navvelenato! é an\vdato K.O. mentre\vcamminavamo!",
  ["_VictoryRoad1FCooltrainerFAfterBattleText"] = "Non volevo per\ndere con nessuno!",
  ["_VictoryRoad1FCooltrainerFBattleText"] = "Chissa' se sei\nall'altezza!",
  ["_VictoryRoad1FCooltrainerFEndBattleText"] = "Ho\nperso!",
  ["_VictoryRoad1FCooltrainerMAfterBattleText"] = "Lo ammetto, sei\npiu' bravo di me!",
  ["_VictoryRoad1FCooltrainerMBattleText"] = "Vedo che vali!\nFammi vedere\vquanto vali!",
  ["_VictoryRoad1FCooltrainerMEndBattleText"] = "Ci\nsperavo...",
  ["_VictoryRoad2FCooltrainerMAfterBattleText"] = "Ti sei meritato la\nVIA VITTORIA!",
  ["_VictoryRoad2FCooltrainerMBattleText"] = "Avanti! Ti concio\nper le feste!",
  ["_VictoryRoad2FCooltrainerMEndBattleText"] = "Mi\nhanno suonato!",
  ["_VictoryRoad2FHikerAfterBattleText"] = "Se ti blocchi,\nprova a spostare\vqualche masso!",
  ["_VictoryRoad2FHikerBattleText"] = "La VIA VITTORIA é\nil test finale per\vgli allenatori!",
  ["_VictoryRoad2FHikerEndBattleText"] = "Aiyah!",
  ["_VictoryRoad2FMoltresBattleText"] = "Gyaoo!",
  ["_VictoryRoad2FSuperNerd1AfterBattleText"] = "Anche {RIVAL} é\npassato di qui!",
  ["_VictoryRoad2FSuperNerd1BattleText"] = "Ah, vuoi sfidare i\nSUPERQUATTRO?",
  ["_VictoryRoad2FSuperNerd1EndBattleText"] = "Mi hai\npreso!",
  ["_VictoryRoad2FSuperNerd2AfterBattleText"] = "Posso batterti in\nquanto a\vconoscenza\vPOKéMON!",
  ["_VictoryRoad2FSuperNerd2BattleText"] = "Se passi di qui,\npuoi incontrare i\vSUPERQUATTRO!",
  ["_VictoryRoad2FSuperNerd2EndBattleText"] = "No!\nIncredibile!",
  ["_VictoryRoad2FSuperNerd3AfterBattleText"] = "Molti allenatori\nrinunciano qui.",
  ["_VictoryRoad2FSuperNerd3BattleText"] = "La VIA VITTORIA é\ntroppo dura?",
  ["_VictoryRoad2FSuperNerd3EndBattleText"] = "Ben\nfatto!",
  ["_VictoryRoad3FCooltrainerF1AfterBattleText"] = "Mi hai mostrato\nquanto valgo!",
  ["_VictoryRoad3FCooltrainerF1BattleText"] = "Ti mostrero'\nquanto vali!",
  ["_VictoryRoad3FCooltrainerF1EndBattleText"] = "Sono\nfuriosa!",
  ["_VictoryRoad3FCooltrainerF2AfterBattleText"] = "Lottando duro, si\ndiventa forti!",
  ["_VictoryRoad3FCooltrainerF2BattleText"] = "Gli allenatori\ncerchano rivali\vpiu' forti!",
  ["_VictoryRoad3FCooltrainerF2EndBattleText"] = "Oh!\nChe forza!",
  ["_VictoryRoad3FCooltrainerM1AfterBattleText"] = "Hai battuto\nGIOVANNI del TEAM\vROCKET?",
  ["_VictoryRoad3FCooltrainerM1BattleText"] = "Ho sentito voci di\nun bimbo prodigio!",
  ["_VictoryRoad3FCooltrainerM1EndBattleText"] = "Le\nvoci erano vere!",
  ["_VictoryRoad3FCooltrainerM2AfterBattleText"] = "Tutti qui vanno\nalla LEGA POKéMON!\vAttento!",
  ["_VictoryRoad3FCooltrainerM2BattleText"] = "Solo i prescelti\npassano di qui!",
  ["_VictoryRoad3FCooltrainerM2EndBattleText"] = "Non ci\nposso credere!",
  ["_ViridianBlackboardBurnText"] = "Una scottatura\nriduce potenza e\vvelocita' e causa\vdanni continui.\vResta anche dopo\vla lotta. Usa\vANTIBRUCIATURA!",
  ["_ViridianBlackboardFrozenText"] = "Se congelato, un\nPOKéMON resta\vimmobile! Non si\vscongela neppure\vdopo la lotta. Usa\vANTIGELO!",
  ["_ViridianBlackboardPoisonText"] = "Da avvelenato, la\nsalute cala\vsempre. Il veleno\vresta anche dopo\vla lotta. Usa un\vANTIDOTO per\vguarirlo!",
  ["_ViridianBlackboardPrlzText"] = "La paralisi puo'\nfallire le mosse!\vResta anche dopo\vla lotta. Usa\vl'ANTIPARALISI per\vcurarlo!",
  ["_ViridianBlackboardSleepText"] = "Un POKéMON non\nattacca se dorme!\vResta addormentato\vanche dopo la\vlotta. Usa la\vSVEGLIA per\vsvegliarlo!",
  ["_ViridianCityFisherReceivedTM42Text"] = "{PLAYER} riceve la\nMT42!",
  ["_ViridianCityFisherTM42ExplanationText"] = "La MT42 contiene\nSOGNIDORO...\v...Ronf...",
  ["_ViridianCityFisherTM42NoRoomText"] = "Hai gia' troppa\nroba con te.",
  ["_ViridianCityGambler1GymAlwaysClosedText"] = "Questa palestra é\nsempre chiusa.\vChissa' chi é il\vCAPOPALESTRA?",
  ["_ViridianCityGambler1GymLeaderReturnedText"] = "Il CAPOPALESTRA é\ntornato!",
  ["_ViridianCityGirlHasntHadHisCoffeeYetText"] = "Oh nonno! Non\nessere cattivo!\vNon ha ancora\vbevuto il caffé.",
  ["_ViridianCityGirlWhenIGoShopText"] = "Quando vado a\nPLUMBEOPOLI, devo\vfare il sentiero\vdel BOSCO\vSMERALDO.",
  ["_ViridianCityGymLockedText"] = "Le porte della\npalestra sono\vchiuse",
  ["_ViridianCityGymSignText"] = "PALESTRA POKéMON\ndi SMERALDOPOLI",
  ["_ViridianCityOldManHadMyCoffeeNowText"] = "Ahh, ho bevuto il\ncaffé e sto bene!\vOra puoi passare!\vHai fretta?",
  ["_ViridianCityOldManKnowHowToCatchPokemonText"] = "Usi il POKéDEX,\nvedo. Catturando\vun POKé MON si\vaggiorna\vautomaticamente.\vChe c'é? Non sai\vcome catturarli?\vTe lo mostro io.",
  ["_ViridianCityOldManSleepyPrivatePropertyText"] = "Non puoi passare!\nQuesta é\vproprieta'\vprivata!",
  ["_ViridianCityOldManTimeIsMoneyText"] = "Il tempo é\ndenaro... Cammina.",
  ["_ViridianCityOldManYouNeedToTheTargetText"] = "Prima devi indebo\nlire il POKéMON.",
  ["_ViridianCityPokecenterGuyText"] = "I CENTRI POKéMON\ncurano i POKéMON\vstanchi, feriti o\vesausti!",
  ["_ViridianCitySignText"] = "SMERALDOPOLI Il\nVerde Paradiso\vEterno",
  ["_ViridianCityTrainerTips1Text"] = "CONSIGLI UTILI\nCattura POKéMON e\vamplia la tua\vcollezione! Piu'\vne hai, piu' é\vfacile lottare!",
  ["_ViridianCityTrainerTips2Text"] = "CONSIGLI UTILI Le\nmosse dei POKé MON\vdipendono dai\vPUNTI POTERE, PP.\vRipristinali ripo\vsando al CENTRO\vPOKéMON!",
  ["_ViridianCityYoungster1Text"] = "Quelle POKé BALL\nalla cintura! Hai\vdei POKéMON! E'\vbello poterli\vportare e usare\vovunque e sempre!",
  ["_ViridianCityYoungster2YouWantToKnowAboutText"] = "Vuoi sapere dei 2\ntipi di POKéMON\vbruco?",
  ["_ViridianForestLeavingSignText"] = "USCITA BOSCO\nSMERALDO\vPLUMBEOPOLI PIU'\vAVANTI",
  ["_ViridianForestNorthGateGrampsText"] = "Hai notato i\ncespugli lungo la\vstrada? Possono\vessere tagliati da\vuna mossa\vspeciale.",
  ["_ViridianForestNorthGateSuperNerdText"] = "Molti POKéMON vi\nvono solo nei\vboschi e grotte.\vDevi cercare ovun\vque per trovarli!",
  ["_ViridianForestSouthGateGirlText"] = "Vai al BOSCO\nSMERALDO? Attento,\vé un labirinto!",
  ["_ViridianForestSouthGateLittleGirlText"] = "RATTATA é piccolo,\nma il suo morso é\vferoce! Ne hai\vuno?",
  ["_ViridianForestTrainerTips1Text"] = "CONSIGLI UTILI Se\nvuoi evitare\vlotte, stai\vlontano dall'erba\valta!",
  ["_ViridianForestTrainerTips2Text"] = "CONSIGLI UTILI\nContatta il\vPROF.OAK dal PC\vper far valutare\vil POKéDEX!",
  ["_ViridianForestTrainerTips3Text"] = "CONSIGLI UTILI Non\nrubare POKéMON\valtrui! Cattura\vsolo quelli\vselvatici!",
  ["_ViridianForestTrainerTips4Text"] = "CONSIGLI UTILI\nIndebolisci i\vPOKéMON prima di\vcatturarli! Se\vsani, pos sono\vfuggire!",
  ["_ViridianForestUseAntidoteSignText"] = "Per il veleno, usa\nl'ANTIDOTO! Nei\vPOKéMON MART!",
  ["_ViridianForestYoungster1Text"] = "Sono venuto qui\ncon degli amici!\vCercano lotte con\vi POKéMON!",
  ["_ViridianForestYoungster2AfterBattleText"] = "Ssh! Spaventerai\ngli insetti!",
  ["_ViridianForestYoungster2BattleText"] = "Ehi! Hai POKé MON!\nForza, lottiamo!",
  ["_ViridianForestYoungster2EndBattleText"] = "No!\nCATERPIE non ce la\vfa!",
  ["_ViridianForestYoungster3AfterBattleText"] = "Accidenti! Ne\ncaturero' di piu'\vforti!",
  ["_ViridianForestYoungster3BattleText"] = "Ehi! Non puoi\nfarti valere se\vsei un allenatore!",
  ["_ViridianForestYoungster3EndBattleText"] = "Eh?\nHo finito i\vPOKéMON!",
  ["_ViridianForestYoungster4AfterBattleText"] = "A volte trovi roba\nper terra! Cerco\vquello che ho\vperso io!",
  ["_ViridianForestYoungster4BattleText"] = "Ehi, aspetta!\nTanta fretta?",
  ["_ViridianForestYoungster4EndBattleText"] = "Mi\narrendo! Sei bravo\vin questo!",
  ["_ViridianForestYoungster5Text"] = "Ho finito le POKé\nBALL per cattura\vre i POKéMON!\vPortane sempre di\vscorta!",
  ["_ViridianGymCooltrainerM1AfterBattleText"] = "Serve potenza per\nreggere il ritmo\vdel nostro CAPO!",
  ["_ViridianGymCooltrainerM1BattleText"] = "Heh! Ti stara'\nfinendo il fiato!",
  ["_ViridianGymCooltrainerM1EndBattleText"] = "Ho\nesaurito la\vspinta!",
  ["_ViridianGymCooltrainerM2AfterBattleText"] = "Il CAPO mi\nsgridera'!",
  ["_ViridianGymCooltrainerM2BattleText"] = "I veri talenti\nvincono con stile!",
  ["_ViridianGymCooltrainerM2EndBattleText"] = "Ho\nperso la presa!",
  ["_ViridianGymCooltrainerM3AfterBattleText"] = "Puoi andare alla\nLEGA POKéMON solo\vbattendo il CAPO!",
  ["_ViridianGymCooltrainerM3BattleText"] = "La palestra fu\nchiusa a lungo, ma\vora il CAPO é\vtornato!",
  ["_ViridianGymCooltrainerM3EndBattleText"] = "Sono\nstato battuto?",
  ["_ViridianGymGiovanniEarthBadgeInfoText"] = "La MEDAGLIA TERRA\nfa' ubbidire i\vPOKéMON di ogni\vlivello! é la\vprova della tua\vmaestria! Con essa\vpuoi entrare nella\vLEGA! é il mio\vdono per la tua\vsfida!",
  ["_ViridianGymGiovanniPostBattleAdviceText"] = "Avendo perso, non\nposso guar dare i\vsubordinati! Il\vTEAM ROCKET é\vfinito per sempre!\vDedicchero' la mia\vvita allo studio!\vCi rivedremo un\vgiorno! Addio!",
  ["_ViridianGymGiovanniPreBattleText"] = "Fwahahaha! Questo\né il mio covo!\vVolevo risurreci\vtare il ROCKET\vqui! Ma mi hai\vripreso! E sia!\vStavolta non mi\vtrattengo!\vAffronterai\vGIOVANNI , il piu'\vgrande!",
  ["_ViridianGymGiovanniReceivedEarthBadgeText"] = "Ha! Una lotta\nintensa! Hai\vvinto! Ecco la\vprova con la\vMEDAGLIA TERRA!",
  ["_ViridianGymGiovanniReceivedTM27Text"] = "{PLAYER} riceve la\nMT27!",
  ["_ViridianGymGiovanniTM27ExplanationText"] = "La MT27 é ABISSO!\nStende i POKéMON\vcon un sol colpo!\vLa feci quando\vgestivo la\vpalestra, molto\vtempo fa...",
  ["_ViridianGymGiovanniTM27NoRoomText"] = "Non hai spazio per\nquesto!",
  ["_ViridianGymGuidePostBattleText"] = "Incredibile!\nGIOVANNI era il\vCAPOPALESTRA qui?",
  ["_ViridianGymGuidePreBattleText"] = "Ehila'! Campione!\nNeanche io so chi\vsia il CAPO di\vQUI! Sara' il piu'\vduro di tutti i\vcapi! Ho sentito\vche amano i\vPOKéMON di tipo\vterra!",
  ["_ViridianGymHiker1AfterBattleText"] = "Non sono ancora\ndegno!",
  ["_ViridianGymHiker1BattleText"] = "Rrrroar! Mi sto\ninfuriando!",
  ["_ViridianGymHiker1EndBattleText"] = "Wargh!",
  ["_ViridianGymHiker2AfterBattleText"] = "Se i miei POKéMON\nfossero bravi a\vKarate come me...",
  ["_ViridianGymHiker2BattleText"] = "Il karate é la\nforma suprema di\varti marziali!",
  ["_ViridianGymHiker2EndBattleText"] = "Atcho!",
  ["_ViridianGymHiker3AfterBattleText"] = "La LEGA POKéMON?\nTu? Non montarti",
  ["_ViridianGymHiker3BattleText"] = "Sono il RE del\nKARATE! Il tuo\vdestino é qui!",
  ["_ViridianGymHiker3EndBattleText"] = "Ayah!",
  ["_ViridianGymRocker1AfterBattleText"] = "Conosci\nl'identita' del\vnostro CAPO?",
  ["_ViridianGymRocker1BattleText"] = "Io e i POKéMON\nfacciamo musica\vmeravigliosa!",
  ["_ViridianGymRocker1EndBattleText"] = "Siete in\nperfetta armonia!",
  ["_ViridianGymRocker2AfterBattleText"] = "Aspetta! Sono\nstato distratto!",
  ["_ViridianGymRocker2BattleText"] = "I tuoi POKéMON\ntremaranno alla\vmia frusta!",
  ["_ViridianGymRocker2EndBattleText"] = "Ahi!\nFrustata!",
  ["_ViridianMartClerkParcelQuestText"] = "Conosci il PROF.\nOAK, giusto? Il\vsuo ordine é\varrivato. Glielo\vporti? {PLAYER}\vprende il PACCO di\vOAK!",
  ["_ViridianMartClerkSayHiToOakText"] = "Ok! Salutami il\nPROF.OAK!",
  ["_ViridianMartClerkYouCameFromPalletTownText"] = "Ehi! Vieni da\nBIANCAVILLA?",
  ["_ViridianMartCooltrainerMText"] = "No! Le POZIONI\nsono esaurite.",
  ["_ViridianMartYoungsterText"] = "Questo negozio\nvende molti\vANTIDOTI",
  ["_ViridianNicknameHouseBaldingGuyText"] = "Inventare i nomi é\nbello ma duro. I\vnomi semplici sono\vi piu' facili da\vricordare.",
  ["_ViridianNicknameHouseLittleGirlText"] = "Anche il mio papa'\nadora i POKéMON.",
  ["_ViridianNicknameHouseSpearowText"] = "SPEARY: Tetweet!",
  ["_ViridianNicknameHouseSpearySignText"] = "SPEAROW Nome:\nSPEARY",
  ["_ViridianPokecenterCooltrainerMText"] = "C'é un CENTRO\nPOKéMON in ogni\vcitta' davanti. E\vnon si paga\vassolutamente\vnulla!",
  ["_ViridianPokecenterGentlemanText"] = "Puoi usare quel PC\nnell'angolo. Me\vl'ha detto la\vreception. Che\vcarini!",
  ["_ViridianSchoolBlackboardText1"] = "La lavagna de\nscrive i cambi di\vSTATO dei POKéMON\vdurante la lotta.",
  ["_ViridianSchoolBlackboardText2"] = "Quale voce vuoi\nleggere?",
  ["_ViridianSchoolHouseBrunetteGirlText"] = "Uff! Studio per\nmemorizzare tutti\vi miei appunti.",
  ["_ViridianSchoolHouseCooltrainerFText"] = "Bene! Leggi\nattentamente la\vlavagna!",
  ["_ViridianSchoolNotebookText1"] = "Guarda il qua\nderno! Prima\vpagina... Le POKé\vBALL ser vono per\vcatturare i\vPOKéMON. Si\vportano fino a 6\vPOKéMON. Chi li\valleva e fa\vlottare é un\vallenatore\vPOKéMON.",
  ["_ViridianSchoolNotebookText2"] = "Seconda pagina...\nUn POKéMON sano é\vduro da catturare,\vindeboliscilo!\vVeleno, ustioni e\vdanni aiutano!",
  ["_ViridianSchoolNotebookText3"] = "Terza pagina...\nGli allenatori\vcercano sfide. Si\vlotta sempre in\vpalestra.",
  ["_ViridianSchoolNotebookText4"] = "Quarta pagina...\nL'obiettivo é bat\vtere gli 8 CAPO.\vFallito cio',\vsi\affrontano... I\vSUPERQUATTRO della\vLEGA POKéMON!",
  ["_ViridianSchoolNotebookText5"] = "RAGAZZA: Ehi! Non\nguardare i miei\vappunti!",
  ["_VitaminNoEffectText"] = "Non avra' alcun\neffetto.",
  ["_VitaminStatRoseText"] = "{RAM:wStringBuffer} di\n{RAM:wNameBuffer} é\vaumentato.",
  ["_WannaTrade1Text"] = "Cerco {RAM:wInGameTradeGiveMonName}!\nVuoi scambiarlo\vcon {RAM:wInGameTradeReceiveMonName}?",
  ["_WannaTrade2Text"] = "Ciao! Vuoi scam\nbiare il tuo\v{RAM:wInGameTradeGiveMonName} per\v{RAM:wInGameTradeReceiveMonName}?",
  ["_WannaTrade3Text"] = "Ciao! Hai un\n{RAM:wInGameTradeGiveMonName}? Vuoi\vscambiarlo per\v{RAM:wInGameTradeReceiveMonName}?",
  ["_WardensHouseDisplayMerchandiseText"] = "Vecchi oggetti\nPOKéMON.",
  ["_WardensHouseDisplayPhotosAndFossilsText"] = "Foto e fossili di\nPOKéMON.",
  ["_WardensHouseWardenGaveTheGoldTeethText"] = "{PLAYER} da' i\nDENTI D'ORO al\vGUARDIANO!",
  ["_WardensHouseWardenGibberish1Text"] = "GUARDIA: Hif fuff\nhefifoo! Ha lof ha\vfeef ee hafahi ho.\vHeff hee fwee!",
  ["_WardensHouseWardenGibberish2Text"] = "Ah howhee ho hoo!\nEef ee hafahi ho!",
  ["_WardensHouseWardenGibberish3Text"] = "Ha? He ohay heh ha\nhoo ee haheh!",
  ["_WardensHouseWardenHM04ExplanationText"] = "GUARDIA: La MN04\ninsegna FORZA!\vPermette ai\vPOKéMON di\vspostare i massi\vfuori dalla lotta.\vAh, hai trovato la\vCASA SEGRETA? Se\vlo fai, vinci una\vMN. Sia la rara MN\vSURF",
  ["_WardensHouseWardenHM04NoRoomText"] = "Il tuo zaino é\npieno zeppo!",
  ["_WardensHouseWardenReceivedHM04Text"] = "{PLAYER} riceve\n{RAM:wStringBuffer}!",
  ["_WardensHouseWardenTeethPoppedInHisTeethText"] = "Il GUARDIANO si é\nmesso i denti!",
  ["_WardensHouseWardenThanksText"] = "GUARDIA: Grazie,\nragazzo! Nessuno\vcapiva una parola.\vNon potevo lavo\vrare cosi'. Prendi\vqualcosa per il\vdisturbo.",
  ["_WarpToLastPokemonCenterText"] = "Vai all'ultimo\nCENTRO POKéMON.",
  ["_WasBlownAwayText"] = "{TARGET} é stato\nspazzato via!",
  ["_WasSeededText"] = "{TARGET} é stato\nparassitato!",
  ["_WhatDoYouWantText"] = "Che cosa vuoi\nfare?",
  ["_WhatGoesAroundComesAroundText"] = "Chi la fa\nl'aspetti!",
  ["_WhatText"] = "Cosa?",
  ["_WhatToDepositText"] = "Che cosa vuoi\ndepositare?",
  ["_WhatToTossText"] = "Che cosa vuoi\nbuttare via?",
  ["_WhatToWithdrawText"] = "Che cosa vuoi\nritirare?",
  ["_WhenYouChangeBoxText"] = "Cambiando BOX, i\ndati saranno\vsalvati. Va bene?",
  ["_WhereWouldYouLikeText"] = "Dove vorresti\nandare?",
  ["_WhichFloorText"] = "Quale piano\npreferisci?",
  ["_WhichMoveToForgetText"] = "Quale mossa deve\nessere\vdimenticata?",
  ["_WhichPrizeText"] = "Quale premio vuoi?",
  ["_WildMonAppearedText"] = "Appare {RAM:wEnemyMonNick}\nselvatico!",
  ["_WildRanText"] = "{RAM:wEnemyMonNick}\nselvatico fugge!",
  ["_WillBeTradedText"] = "{RAM:wNameOfPlayerMonToBeTraded} e\n{RAM:wNameBuffer} saranno\vscambiati.",
  ["_WithExpAllText"] = "con EXP.TUTTI,",
  ["_WithdrawHowManyText"] = "Quanti?",
  ["_WithdrewItemText"] = "Hai ritirato\n{RAM:wNameBuffer}.",
  ["_WokeUpText"] = "{USER} si é\nsvegliato!",
  ["_WontObeyText"] = "{RAM:wBattleMonNick} non\nobbedisce!",
  ["_WouldYouLikeToSaveText"] = "Vuoi SALVARE il\ngioco?",
  ["_WrongMon1Text"] = "Cosa? Non é\n{RAM:wInGameTradeGiveMonName}!\vTrovane uno e\vtorna qui!",
  ["_WrongMon2Text"] = "Mhm? Questo non é\n{RAM:wInGameTradeGiveMonName}. Pensa\va me se ne trovi\vuno.",
  ["_WrongMon3Text"] = "...Questo non é un\n{RAM:wInGameTradeGiveMonName}. Se ne\vtrovi uno,\vscambialo con me!",
  ["_YeahText"] = "Si'!",
  ["_YourNameIsText"] = "Giusto! Ti chiami\nproprio {PLAYER}!",





  ["MelanieText1"] = "Curo i POKéMON\nferiti. Ho curato\vquesto BULBASAUR\vfino a farlo\vguarire. Ora ha\vbisogno di un\vbravo allenatore.",
  ["MelanieText2"] = "Ho un'idea! Vuoi\nprenderti cura di\vquesto BULBASAUR?",
  ["MelanieText3"] = "Abbi cura di\nBULBASAUR!",
  ["MelanieText4"] = "Come sta il tuo\nBULBASAUR?",
  ["MelanieText5"] = "Oh... Che\npeccato...",
  ["OAK: Look, {PLAYER}! Do\nyou see that ball\non the table?"] = "OAK: Guarda {PLAYER}!\nVedi quella sfera\nsul tavolo?",
  ["SilphCo2FSilphWorkerFPleaseTakeThisText"] = "Aaaaah! No! Aiuto!\nAh, non sei del\vTEAM ROCKET.\vPensavo...\vPerdonami! Prendi\vquesto, ti prego!",
  ["SummerBeachHouseSurfinDudeText1"] = "Uau! Il tuo\nPIKACHU sa usare\vSURF! Allora non\vsono il solo...\vFantastico! Ora\vpuoi fare SURF\vinsieme a me! Ti\vva?",
  ["SummerBeachHouseSurfinDudeText2"] = "Vieni a fare SURF\nquando vuoi,\vamico!",
  ["SummerBeachHouseSurfinDudeText3"] = "Vuoi fare SURF?",
  ["SummerBeachHouseSurfinDudeText4"] = "Oggi c'e' una gran\nbella onda!",
  ["_MrPsychicsHouseMrPsychicNoMoreText"] = "...Aumm...",
  ["_MrPsychicsHouseMrPsychicText"] = "...Aspetta! Non\ndire una parola!\vVolevi questo!",
  ["_MtMoonJessieJamesText1"] = "Fermati li'!",
  ["_MtMoonJessieJamesText2"] = "Quel fossile e'\ndel TEAM ROCKET!\vArrenditi subito o\vpreparati a\vcombattere!",
  ["_MtMoonJessieJamesText3"] = "Un ragazzino ci ha\nbattuti?",
  ["_MtMoonJessieJamesText4"] = "Il TEAM ROCKET\nparte alla carica\valla velocita'\vdella luce!",
  ["_MtMoonPokecenterMagikarpSalesmanOfferText"] = "UOMO: Salve! Ho\nun'offerta\vspeciale per te!\vTi daro' un\vfantastico\vMAGIKARP per soli\v500¥! Che ne dici?",
  ["_OaksLabChooseMonText"] = "OAK: Eh? {RIVAL}?\nPerche' sei gia'\vqui? Ti avevo\vdetto di venire\vpiu' tardi... Beh,\vpazienza! Aspetta\vun attimo. Guarda,\v{PLAYER}! Vedi\vquella sfera sul\vtavolo? Si chiama\vPOKé BALL.\vContiene un\vPOKéMON. Puoi\vprenderla! Forza,\ve' tua!",
  ["_OaksLabOak1GoAheadItsYours"] = "Forza, e' tuo!",
  ["_OaksLabOak1YouShouldTalkToIt"] = "OAK: Dovresti\nparlargli per\vvedere come sta.",
  ["_OaksLabOakGivesText"] = "OAK: {PLAYER},\nquesto e' il\vPOKéMON che ho\vcatturato. Puoi\vtenerlo tu. L'ho\vcatturato da poco,\vquindi e' ancora\vselvatico.",
  ["_OaksLabPikachuDislikesPokeballsText1"] = "OAK: Cosa?",
  ["_OaksLabPikachuDislikesPokeballsText2"] = "OAK: Guarda qui!\nE' strano, ma\vsembra che il tuo\vPIKACHU odi le\vPOKé BALL. Tienilo\vfuori con te. Lo\vrendera' felice!\vPuoi parlargli per\vvedere come sta.",
  ["_OaksLabPikachuText"] = "OAK: Forza, e'\ntuo!",
  ["_OaksLabReceivedText"] = "{PLAYER} riceve\n{RAM:wNameBuffer}!",
  ["_OaksLabRivalIllGetABetterPokemonThanYou"] = "{RIVAL}: Uffa!\nPrendero' un\vPOKéMON migliore\vdel tuo!",
  ["_OaksLabRivalTakesText1"] = "{RIVAL}: Non se ne\nparla! {PLAYER}, io\vvoglio questo!",
  ["_OaksLabRivalTakesText2"] = "{RIVAL} prende il\nPOKéMON!",
  ["_OaksLabRivalTakesText3"] = "OAK: {RIVAL}! Ma\ncosa fai?",
  ["_OaksLabRivalTakesText4"] = "{RIVAL}: Nonno, io\nvoglio questo!",
  ["_OaksLabRivalTakesText5"] = "OAK: Ma io... Ah,\ne va bene. Prendi\vpure quello. Tanto\vvolevo darne uno\vanche a te...\v{PLAYER}, vieni\vqui.",
  ["_OaksLabThatsAPokeball"] = "Questa e' una POKé\nBALL!",
  ["_OfficerJennyText1"] = "Ho appena preso\nquesto SQUIRTLE\vche creava\vproblemi. Ha\vbisogno di un\vbravo allenatore\vche lo educhi.",
  ["_OfficerJennyText2"] = "Hai la MEDAGLIA\nTUONO!? Devi\vessere un bravo\vallenatore! Ho\vpreso questo\vSQUIRTLE che dava\vsempre problemi.\vVorresti\vallenarlo?",
  ["_OfficerJennyText3"] = "OK! Abbi cura di\nSQUIRTLE!",
  ["_OfficerJennyText4"] = "Oh... Che cosa\nfaro' adesso?",
  ["_OfficerJennyText5"] = "Come sta andando\ncon SQUIRTLE?",
  ["_PalletTownOakComeWithMe"] = "Vieni con me!",
  ["_PalletTownOakThatWasCloseText"] = "C'e' mancato poco!\nPOKéMON selvatici\vvivono nell'erba!",
  ["_PalletTownOakWhewText"] = "Uff...",
  ["_PokemonTowerJessieJamesText1"] = "Fermati li'!",
  ["_PokemonTowerJessieJamesText2"] = "Il vecchio laggiu'\nvoleva lamentarsi,\vcosi' gli daremo\vuna lezione.\vArrenditi subito o\vpreparati a\vcombattere!",
  ["_PokemonTowerJessieJamesText3"] = "Te ne pentirai,\nragazzetto!",
  ["_PokemonTowerJessieJamesText4"] = "Sembra che il TEAM\nROCKET decolli di\vnuovo!",
  ["_RocketHideoutJessieJamesText1"] = "Non fare un solo\npasso, moccioso!",
  ["_RocketHideoutJessieJamesText2"] = "Come hai osato\numiliarci sul\vMONTE LUNA?! E'\vora della resa dei\vconti!",
  ["_RocketHideoutJessieJamesText3"] = "Maledetto\nmoccioso!",
  ["_RocketHideoutJessieJamesText4"] = "Sembra che il TEAM\nROCKET decolli di\vnuovo!",
  ["_Route24DamianText1"] = "Non sono bravo ad\nallenare i\vPOKéMON. Penso che\vdovrei liberare il\vmio CHARMANDER...\vSe mi prometti che\vne avrai cura, te\vlo regalo. Va\vbene?",
  ["_Route24DamianText2"] = "Abbi cura del mio\nCHARMANDER!",
  ["_Route24DamianText3"] = "Ah... Allora e'\nmeglio liberarlo.",
  ["_Route24DamianText4"] = "Come sta il mio\nCHARMANDER?",
  ["_SSAnne1FRoomsGentleman2BattleText"] = "Moccioso! Che\nsfacciato!",
  ["_SSAnneKitchenCook2Text"] = "Ho visto una sfera\nmolto strana nel\vcestino.",
  ["_SilphCo7FSilphWorkerM1ThankYouText"] = "Ah! Ehi! Non sei\ndel TEAM ROCKET!\vSei venuto a\vsalvarmi? Grazie\vmille! Voglio che\vtu abbia questo\vPOKéMON per averci\vsalvati.",
  ["_SilphCo9FNurseText"] = "Non arrenderti!",
  ["_SilphCo9FNurseText2"] = "Grazie mille!",
  ["_SilphCo9FNurseYouLookTiredText"] = "Sembri molto\nstanco! Dovresti\vriposarti un po'!",
  ["_SilphCoJessieJamesText1"] = "Fermati li',\nmoccioso!",
  ["_SilphCoJessieJamesText2"] = "Il nostro CAPO e'\nin una riunione!\vNon disturbarlo!",
  ["_SilphCoJessieJamesText3"] = "Come sempre...",
  ["_SilphCoJessieJamesText4"] = "TEAM ROCKET,\npronti a decollare\valla velocita'\vdella luce! Di\vnuovo...",
  ["_StoppedEvolvingText"] = "Uh? {RAM:wStringBuffer} ha\nsmesso di\vevolversi!",
  ["_StrengthsAndWeaknessesText"] = "Tutti i tipi di\nPOKéMON hanno\vpunti di forza e\vdi debolezza\vcontro gli altri\vtipi.",
  ["_SummerBeachHousePoster1Text1"] = "Appunti del\nMAESTRO\vSURFISTA... Quando\ventro nel tubo, la\vmusica parte a\vpalla!",
  ["_SummerBeachHousePoster1Text2"] = "30 anni di onde!\nMAESTRO SURFISTA",
  ["_SummerBeachHousePoster2Text1"] = "CONSIGLI SURF 1\nDopo un salto,\vallinea la tavola\vcon l'onda per un\veffetto super!",
  ["_SummerBeachHousePoster2Text2"] = "CASA SULLA\nSPIAGGIA ESTIVA\vPOKéMON Benvenuti!",
  ["_SummerBeachHousePoster3Text1"] = "CONSIGLI SURF 2\nFare piu'\vrotazioni in un\vsalto e' troppo\vforte!",
  ["_SummerBeachHousePoster3Text2"] = "Il mare unisce\ntutti i surfisti!",
  ["_SummerBeachHousePrinterText1"] = "E' una specie di\nmacchinario...",
  ["_SummerBeachHousePrinterText2"] = "STAMPANTE DELLA\nCASA SULLA\vSPIAGGIA ESTIVA\vPOKéMON...",
  ["_SummerBeachHousePrinterText3"] = "Mostra i tuoi\nrecord. Vuoi\vSTAMPARE?",
  ["_SummerBeachHousePrinterText4"] = "STAMPANTE DELLA\nCASA SULLA\vSPIAGGIA ESTIVA\vPOKéMON... Mostra\vi tuoi record.\vVuoi STAMPARE?",
  ["_SummerBeachHousePrinterText5"] = "STAMPA completata!",
  ["_SummerBeachHousePrinterText6"] = "Errore di stampa!",
  ["_VermilionGymTrashFailText"] = "No! C'e' solo\nspazzatura qui.\vEhi! Le serrature\velettroniche si\vsono riattivate!",
  ["_ViridianCityOldManLosingMyTouchText"] = "Non ha funzionato\ncome pensavo. Sto\vperdendo il mio\vtocco... Ho finito\vanche le POKé\vBALL. Andro' a\vcomprarne altre al\vBAZAR.",
  ["_ViridianCityOldManYouNeedToWeakenTheTargetText"] = "Prima di tutto,\ndevi indebolire il\vPOKéMON.",
  ["_ViridianForestCooltrainerFAfterBattleText"] = "Ho cercato\ndappertutto, ma\vnon ho trovato\vnessun PIKACHU!",
  ["_ViridianForestCooltrainerFBattleText"] = "Ehi, hai un\nPIKACHU?",
  ["_ViridianForestCooltrainerFEndBattleText"] = "Oh,\nno! Davvero?",
  ["_ViridianForestYoungster5AfterBattleText"] = "METAPOD e' forte\nperche' la sua\vmiglior difesa e'\vl'ATTACCO!",
  ["_ViridianForestYoungster5BattleText"] = "Saro' il migliore.\nNon potrai mai\vbattermi!",
  ["_ViridianForestYoungster5EndBattleText"] = "Dopo\ntutto quello che\vho fatto...",
  ["_ViridianForestYoungster6Text"] = "Ho finito le POKé\nBALL per catturare\valtri POKéMON! E'\vsempre meglio\vavere qualche\vscorta!",

  ["FanClubChairPrintText1"] = "Ciao, {PLAYER}! Hai\ngia' visto le mie\vfoto di #MON? Le\vho messe in\vcornice e appese\vla' sulla parete.\vAh, gia'! Vuoi che\vti faccia una foto\vdei tuoi POKéMON",
  ["FanClubChairPrintText2"] = "No? Che delusione",
  ["FanClubChairPrintText3"] = "Ecco fatto",
  ["FanClubChairPrintText4"] = "Possiamo STAMPARE\nin un altro\vmomento",
  ["SSAnneKitchenCook7EelsAuBarbecueText"] = "Spiedini di\nanguilla! Temo che\vgli invitati\vfaranno una\vrivolta",
  ["SSAnneKitchenCook7PrimeBeefSteakText"] = "Bistecca di manzo!\nMa avremo\vabbastanza\vbistecche",
  ["SSAnneKitchenCook7SalmonDuSaladText"] = "Insalata di\nsalmone! Eppure\vgli invitati\vprotesteranno\vperché é di nuovo\vpesce",
  ["TMNotebookText"] = "É un volantino\nsulle MT. ... Ci\vsono 50 MT in\vtotale. Esistono\vanche 5 SM che si\vpossono usare piu'\vvolte. SILPH SPA",
  ["TeachingHMsText"] = "Quando un POKéMON\nimpara una MO, la\vmossa non potra'\vpiu' essere\vdimenticata. É\vbene pensarci bene\vprima di insegnare\vuna mossa MO",
  ["ViridianCityFisherYouCanHaveThisText"] = "Uffa! De me ne\nsono addormentato\val sole. Ho\vsognato che un\vDROWZEE si\vmangiava i miei\vsogni... Cos'é\vquesto? Da dove\vspunta questa MT?\vChe paura! Tieni,\vprendi questa MT",
  ["_FanClubChairPrintText1"] = "Ciao, {PLAYER}! Hai\ngia' visto le mie\vfoto di #MON? Le\vho messe in\vcornice e appese\vla' sulla parete.\vAh, gia'! Vuoi che\vti faccia una foto\vdei tuoi POKéMON",
  ["_FanClubChairPrintText2"] = "No? Che delusione",
  ["_FanClubChairPrintText3"] = "Ecco fatto",
  ["_FanClubChairPrintText4"] = "Possiamo STAMPARE\nin un altro\vmomento",
  ["_GameCornerClerkCantAffordTheCoinsText"] = "",
  ["_GameCornerClerkCoinCaseIsFullText"] = "",
  ["_GameCornerClerkDoYouNeedSomeGameCoinsText"] = "",
  ["_GameCornerClerkDontHaveCoinCaseText"] = "",
  ["_GameCornerClerkPleaseComePlaySometimeText"] = "",
  ["_GameCornerClerkThanksHereAre50CoinsText"] = "",
