  ["_OaksLabRivalMyPokemonHasGrownStrongerText"] = "{RIVAL}: Nonno, il\nmio POKéMON é\vcresciuto un\vsacco! Guardati\vquesto",
  ["_PokemonFanClubClefairyFanBetterText"] = "Bah! Il mio\nCLEFAIRY é due\vvolte piu' carino\vdi quel pesce",
  ["_PokemonFanClubClefairyFanNormalText"] = "Non vuoi ammirare\nl'adorabile coda\vdel mio CLEFAIRY",
  ["_PokemonFanClubClefairyFanText"] = "Il passatempo del\nostro PRESIDENTE\vora é fotografare\vi POKéMON. Mi ha\vdato una foto\vSTAMPATA del mio\vCLEFAIRY",
  ["_PokemonFanClubClefairyText"] = "CLEFAIRY: Fiffii",
  ["_PokemonFanClubSeelFanText"] = "Ho bisogno di un\ncavo per\vconnettere e\vSTAMPARE una foto\vdel mio SEEL",
  ["_SSAnneKitchenCook7EelsAuBarbecueText"] = "Spiedini di\nanguilla! Temo che\vgli invitati\vfaranno una\vrivolta",
  ["_SSAnneKitchenCook7PrimeBeefSteakText"] = "Bistecca di manzo!\nMa avremo\vabbastanza\vbistecche",
  ["_SSAnneKitchenCook7SalmonDuSaladText"] = "Insalata di\nsalmone! Eppure\vgli invitati\vprotesteranno\vperché é di nuovo\vpesce",
  ["_SavingText"] = "Salvataggio in\ncorso",
  ["_SilphCo2FSilphWorkerFPleaseTakeThisText"] = "Aaaaah! No! Fermo!\nAiuto! Ah, non sei\vun membro del TEAM\vROCKET. Pensavo...\vPerdonami. Tieni,\vprendi questo",
  ["_TeachingHMsText"] = "Quando un POKéMON\nimpara una MO, la\vmossa non potra'\vpiu' essere\vdimenticata. É\vbene pensarci bene\vprima di insegnare\vuna mossa MO",
  ["_ViridianCityFisherYouCanHaveThisText"] = "Uffa! De me ne\nsono addormentato\val sole. Ho\vsognato che un\vDROWZEE si\vmangiava i miei\vsogni... Cos'é\vquesto? Da dove\vspunta questa MT?\vChe paura! Tieni,\vprendi questa MT",
  ["_ViridianSchoolHouseLittleGirlText"] = "Mia sorella ha\ndetto che i\vPOKéMON diventano\vpiu' docili se li\vtratti con affetto",

  
}